/* 橡木鎮名冊的故事覆蓋層。只帶 id 與 story，由 scripts/build-oakvale-branches.js 產生。 */
window.SERIES = window.SERIES || [];
window.SERIES.push({"id":"oakvale-roster","characters":[{"id":"gretchen_tithehammer","story":{"quote":"十七枚金幣，十七個名字。沒有人來捐過。摸上去是體溫。","background":"葛蕾琴·獻金鎚在晨光神殿管了四十年的帳。她為每一枚捐款負責，也會在沒人看見的時候，替付不起療癒費用的人補上差額。她補得很安靜，安靜到連神父都以為那些錢是忽然多出來的善心。","ideal":"每一枚錢都要對得上一個還活著、或至少被記得的人。","bond":"地庫裡那十七枚刻著名字的金幣。她不肯入帳，也不肯上繳。","flaw":"帳一旦對不上，她會先懷疑人，包括自己。","chapters":[{"title":"體溫","text":"秋末清點，地庫多出一筆沒有募捐紀錄的錢。十七枚金幣，每枚刻一個名字，都在失蹤名單上。葛蕾琴沒有叫衛兵。她把金幣一枚一枚焐在手心，確認那不是錯覺。是體溫。像有人剛剛還把它們握過。"},{"title":"廚房的桌子","text":"她把這件事带到孤兒院的廚房，因為阿嘉莎的桌子是鎮上少數還肯讓人把壞消息放下的地方。十一個人站著。墓碑被重刻、信寄不進房間、旗上多繡了臉。葛蕾琴把金幣排成一列，說：先別解釋。先認。誰認得誰，就站到那枚後面。"},{"title":"點名","text":"封印之夜鎮長問「十七個呢」，沒有人答。三天後葛蕾琴把金幣排在神殿前庭。碑語史家唸一個名字，就有一個記得的人站出來說「在」。第十七個唸完，她才把金幣收進匣子，匣子不鎖。她寫給帳冊的註只有四個字：尚未入帳。人還沒有回來的錢，不能算捐款。"}],"relations":[{"id":"mara_epitaph","text":"唸名字的人。葛蕾琴負責在每個名字後面等一個肯答「在」的人"},{"id":"agatha","text":"第一次把十一件怪事放上同一張桌子的廚房主人"},{"id":"edda","text":"問「十七個呢」的鎮長。葛蕾琴沒有在那一夜回答，三天後用點名回答"},{"id":"ambrose","text":"把點名寫進第一百五十七封信的神父"}]}},{"id":"mara_epitaph","story":{"quote":"名字被磨掉的碑，底下的石頭還記得筆畫。","background":"瑪拉·碑語在墓園裡拓碑。她討厭把歷史當故事講，對死者的名字卻近乎苛刻。別人說「大概是這個字」，她會把拓片推回去，要人再看一次刀痕的深淺。","ideal":"被磨掉的名字要拓回來，一筆都不許猜。","bond":"十七塊被重刻過的碑。原名在石理裡，不在新漆上。","flaw":"為了一個筆畫可以讓整隊人在寒風裡等她。","chapters":[{"title":"重刻","text":"今年的碑乾淨得不正常。新漆下面有舊刀痕。瑪拉拓了三張才敢說：有人把名字換了。換上去的名字也是真人，只是不屬於這座坟。像把一個還在等的人，提前埋進另一個人的結局。"},{"title":"筆畫","text":"司庫的金幣對得上她拓回來的十七個舊名。其中一個筆畫她拓了四次，因為風太大，紙一直破。破了她就換紙。阿嘉莎後來問她冷不冷。她說冷。然後把第四張拓片放上桌，邊緣還是皺的。"},{"title":"在","text":"冬至前夜她負責唸。她唸得很慢，慢到像在把筆畫還給空氣。每唸完一個，就有人答「在」。答的人不是失蹤者本人。瑪拉不糾正。她在名冊邊欄寫：由某人代答。代答也是一種沒有被磨掉。"}],"relations":[{"id":"gretchen_tithehammer","text":"帶著十七枚體溫金幣來對名字的司庫"},{"id":"imani_ghostbloom","text":"墓園裡先看見幽靈花長滿的植物學家。花長在瑪拉說「有東西留下來」的地方"},{"id":"echo","text":"另一本冊子裡第一個從無名潮走回來的人。瑪拉後來把代答的名單托給了那一邊"}]}},{"id":"imani_ghostbloom","story":{"quote":"我不替誰哭。我替誰點名。","ideal":"名字比消息重要","bond":"那枚刻著名字、摸上去還有體溫的金幣。","flaw":"等一個人等到不肯聽「別等了」。伊瑪妮·幽花把這句話留在橡木鎮·晨光神殿。","chapters":[{"title":"多出來的那一個","text":"晨光神殿後的墓園裡，伊瑪妮舉起一株發光的幽靈花，說這種花只在有東西留下來的地方生根，而它今年長滿了整片墓地"},{"title":"相信","text":"那個孩子說他看見了那條巷子。三年來沒人信。伊瑪妮·幽花蹲下來，用墓園植物學家的方式問了三個只有真的看見過的人才答得出的問題。孩子全答對了。伊瑪妮·幽花站起來說：帶我去。"},{"title":"在","text":"冬至前夜，碑語史家唸到那個名字。伊瑪妮·幽花站出來，說「在」。替她答的。神殿前庭很冷，沒有人動。回到橡木鎮·晨光神殿之後，伊瑪妮·幽花把那個名字寫在自己每天最先看見的地方。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。伊瑪妮·幽花認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。伊瑪妮·幽花給了她其中一個筆畫"}]}},{"id":"maevra_bonecipher","story":{"quote":"等一個人最難的不是等，是別人叫你別等了。","ideal":"把不見的人留下來。梅芙菈·骨密把這句話留在橡木鎮·晨光神殿。","bond":"十七個名字裡的一個。不說是誰。梅芙菈·骨密把這句話留在橡木鎮·晨光神殿。","flaw":"把「不會吧」三個字記成債。梅芙菈·骨密把這句話留在橡木鎮·晨光神殿。","chapters":[{"title":"多出來的那一個","text":"神殿停靈室裡，梅芙菈請你查看一具從遺跡運回的骸骨；它的指骨在無人碰觸時仍反覆拼出一個地名"},{"title":"泊在岸邊","text":"有一個人的夢泊在岸邊，身體在鎮上照常過日子。梅芙菈·骨密去看了那個「身體」：買菜、點頭、付錢，就是不叫任何人的名字。梅芙菈·骨密叫了她的名字三次。第三次，那人哭了，自己不知道為什麼。"},{"title":"一百五十七","text":"神父寫第一百五十七封信的時候，梅芙菈·骨密在旁邊，替那個名字補了一句別人不知道的事：左撇子、怕狗、欠梅芙菈·骨密一頓飯。神父一字不改地寫了進去。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。梅芙菈·骨密認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。梅芙菈·骨密給了她其中一個筆畫"}]}},{"id":"halvora_bannerthaw","story":{"quote":"名字被磨掉的碑，底下的石頭還記得筆畫。人也一樣。","ideal":"先數，再找。哈爾芙菈·融旗把這句話留在橡木鎮·傭兵訓練場。","bond":"阿嘉莎的廚房桌——第一次把所有怪事放在同一張桌上的地方。哈爾芙菈·融旗把這句話留在橡木鎮·傭兵訓練場。","flaw":"認得出名字，卻不願說出是哪一個。哈爾芙菈·融旗把這句話留在橡木鎮·傭兵訓練場。","chapters":[{"title":"多出來的那一個","text":"傭兵訓練場邊，哈爾芙菈在練習明日的巨旗巡遊，旗桿卻愈舉愈重；她說旗面上多繡了幾張臉，而那些人都是今年失蹤的鎮民"},{"title":"同一張桌","text":"阿嘉莎的廚房只有一張桌，那晚擠了十一個人。哈爾芙菈·融旗把自己手上那件怪事放上去——做節慶巨旗掌旗手才看得出來的那種——然後聽別人的。十一件事拼起來，是同一條巷子。"},{"title":"第二盞燈","text":"點名到第十七個，山上那第二盞燈亮了一下。哈爾芙菈·融旗看見了。哈爾芙菈·融旗沒有說「他回來了」，也沒有說「他走了」，只是把節慶巨旗掌旗手的事做完，然後三年來第一次睡了整夜。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。哈爾芙菈·融旗認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。哈爾芙菈·融旗給了她其中一個筆畫"}]}},{"id":"raen_duskarchive","story":{"quote":"「不會吧」——我說過這三個字。從那天起我不再說。","ideal":"替還沒回來的人留一個位子。芮恩·暮檔把這句話留在鎮外·古地城入口。","bond":"那枚刻著名字、摸上去還有體溫的金幣。芮恩·暮檔把這句話留在鎮外·古地城入口。","flaw":"點名時會停太久。芮恩·暮檔把這句話留在鎮外·古地城入口。","chapters":[{"title":"多出來的那一個","text":"遺跡營地中，芮恩替一具無名骸骨找回身分，卻發現死者的姓名正刻在隊伍受雇尋找的古代守衛胸口"},{"title":"第三年","text":"芮恩·暮檔翻出三年前的紀錄。那時芮恩·暮檔在鎮外·古地城入口，有人說少了一個人，芮恩·暮檔說「不會吧」。這次芮恩·暮檔把那一頁撕下來，釘在名單旁邊。"},{"title":"留著","text":"鎮慢慢學會沒有熔爐的日子。芮恩·暮檔的鎮外·古地城入口留著一個位子、一只碗、一行名字。有人問為什麼不收起來。芮恩·暮檔說：不見了和死了是兩件事。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。芮恩·暮檔認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。芮恩·暮檔給了她其中一個筆畫"}]}},{"id":"calliope_chalkriot","story":{"quote":"「不見了」和「死了」是兩件事。前者還欠人一個答案。卡莉俄珮·粉筆暴把這句話留在橡木鎮·後巷。","ideal":"名字比消息重要。卡莉俄珮·粉筆暴把這句話留在橡木鎮·後巷。","bond":"十七個名字裡的一個。不說是誰。卡莉俄珮·粉筆暴把這句話留在橡木鎮·後巷。","flaw":"等一個人等到不肯聽「別等了」。卡莉俄珮·粉筆暴把這句話留在橡木鎮·後巷。","chapters":[{"title":"多出來的那一個","text":"後巷牆面，卡莉俄珮的幻術塗鴉開始重播一樁三年前無人報案的案件，畫面唯一缺少的正是加害者的臉"},{"title":"相信","text":"那個孩子說他看見了那條巷子。三年來沒人信。卡莉俄珮·粉筆暴蹲下來，用街頭幻術壁畫家的方式問了三個只有真的看見過的人才答得出的問題。孩子全答對了。卡莉俄珮·粉筆暴站起來說：帶我去。"},{"title":"在","text":"冬至前夜，碑語史家唸到那個名字。卡莉俄珮·粉筆暴站出來，說「在」。替她答的。神殿前庭很冷，沒有人動。回到橡木鎮·後巷之後，卡莉俄珮·粉筆暴把那個名字寫在自己每天最先看見的地方。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。卡莉俄珮·粉筆暴認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。卡莉俄珮·粉筆暴給了她其中一個筆畫"}]}},{"id":"kalla_peakpost","story":{"quote":"數到十六的時候我停了很久。第十七個是我認識的。卡菈·峰郵把這句話留在鎮廣場·信鴉塔。","ideal":"把不見的人留下來。卡菈·峰郵把這句話留在鎮廣場·信鴉塔。","bond":"阿嘉莎的廚房桌——第一次把所有怪事放在同一張桌上的地方。卡菈·峰郵把這句話留在鎮廣場·信鴉塔。","flaw":"把「不會吧」三個字記成債。卡菈·峰郵把這句話留在鎮廣場·信鴉塔。","chapters":[{"title":"多出來的那一個","text":"信鴉塔外的石階上，高山信使卡菈卸下沉重的背架，平靜地說有一封該送進鎮上的信，她連續三天都找不到收件的房間"},{"title":"泊在岸邊","text":"有一個人的夢泊在岸邊，身體在鎮上照常過日子。卡菈·峰郵去看了那個「身體」：買菜、點頭、付錢，就是不叫任何人的名字。卡菈·峰郵叫了她的名字三次。第三次，那人哭了，自己不知道為什麼。"},{"title":"一百五十七","text":"神父寫第一百五十七封信的時候，卡菈·峰郵在旁邊，替那個名字補了一句別人不知道的事：左撇子、怕狗、欠卡菈·峰郵一頓飯。神父一字不改地寫了進去。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。卡菈·峰郵認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。卡菈·峰郵給了她其中一個筆畫"}]}},{"id":"tobin_bluescarf","story":{"quote":"我不替誰哭。我替誰點名。托賓·藍巾把這句話留在鎮廣場·信鴉塔。","ideal":"先數，再找。托賓·藍巾把這句話留在鎮廣場·信鴉塔。","bond":"那枚刻著名字、摸上去還有體溫的金幣。托賓·藍巾把這句話留在鎮廣場·信鴉塔。","flaw":"認得出名字，卻不願說出是哪一個。托賓·藍巾把這句話留在鎮廣場·信鴉塔。","chapters":[{"title":"多出來的那一個","text":"信鴉塔的階梯上，信使托賓藍圍巾一甩衝到你面前，喘著氣說有封信他送了三次都被「退回來」，收件人住在一條不存在的走廊"},{"title":"同一張桌","text":"阿嘉莎的廚房只有一張桌，那晚擠了十一個人。托賓·藍巾把自己手上那件怪事放上去——做快捷信使才看得出來的那種——然後聽別人的。十一件事拼起來，是同一條巷子。"},{"title":"第二盞燈","text":"點名到第十七個，山上那第二盞燈亮了一下。托賓·藍巾看見了。托賓·藍巾沒有說「他回來了」，也沒有說「他走了」，只是把快捷信使的事做完，然後三年來第一次睡了整夜。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。托賓·藍巾認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。托賓·藍巾給了她其中一個筆畫"}]}},{"id":"miravel_windroost","story":{"quote":"等一個人最難的不是等，是別人叫你別等了。米菈薇爾·風棲把這句話留在鎮廣場·信鴉塔。","ideal":"替還沒回來的人留一個位子。米菈薇爾·風棲把這句話留在鎮廣場·信鴉塔。","bond":"十七個名字裡的一個。不說是誰。米菈薇爾·風棲把這句話留在鎮廣場·信鴉塔。","flaw":"點名時會停太久。米菈薇爾·風棲把這句話留在鎮廣場·信鴉塔。","chapters":[{"title":"多出來的那一個","text":"信鴉塔裡，米菈薇爾清出一疊寄不出去的信；收件地址都是同一間早已不存在的教室，而信紙每天自行多出一行新字"},{"title":"第三年","text":"米菈薇爾·風棲翻出三年前的紀錄。那時她在鎮廣場·信鴉塔，有人說少了一個人，米菈薇爾·風棲說「不會吧」。這次米菈薇爾·風棲把那一頁撕下來，釘在名單旁邊。"},{"title":"留著","text":"鎮慢慢學會沒有熔爐的日子。米菈薇爾·風棲的鎮廣場·信鴉塔留著一個位子、一只碗、一行名字。有人問為什麼不收起來。米菈薇爾·風棲說：不見了和死了是兩件事。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。米菈薇爾·風棲認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。米菈薇爾·風棲給了她其中一個筆畫"}]}},{"id":"ummara_stoneparry","story":{"quote":"名字被磨掉的碑，底下的石頭還記得筆畫。人也一樣。烏瑪菈·石擋把這句話留在橡木鎮·傭兵訓練場。","ideal":"名字比消息重要。烏瑪菈·石擋把這句話留在橡木鎮·傭兵訓練場。","bond":"阿嘉莎的廚房桌——第一次把所有怪事放在同一張桌上的地方。烏瑪菈·石擋把這句話留在橡木鎮·傭兵訓練場。","flaw":"等一個人等到不肯聽「別等了」。烏瑪菈·石擋把這句話留在橡木鎮·傭兵訓練場。","chapters":[{"title":"多出來的那一個","text":"訓練場上，烏瑪菈的合格銅牌少了三枚，而營區名冊裡從來沒有那三個人的入伍紀錄"},{"title":"相信","text":"那個孩子說他看見了那條巷子。三年來沒人信。烏瑪菈·石擋蹲下來，用城衛隊近戰教官的方式問了三個只有真的看見過的人才答得出的問題。孩子全答對了。烏瑪菈·石擋站起來說：帶我去。"},{"title":"在","text":"冬至前夜，碑語史家唸到那個名字。烏瑪菈·石擋站出來，說「在」。替她答的。神殿前庭很冷，沒有人動。回到橡木鎮·傭兵訓練場之後，烏瑪菈·石擋把那個名字寫在自己每天最先看見的地方。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。烏瑪菈·石擋認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。烏瑪菈·石擋給了她其中一個筆畫"}]}},{"id":"orrik_flintward","story":{"quote":"「不會吧」——我說過這三個字。從那天起我不再說。奧里克·燧衛把這句話留在鎮外·古地城入口。","ideal":"把不見的人留下來。奧里克·燧衛把這句話留在鎮外·古地城入口。","bond":"那枚刻著名字、摸上去還有體溫的金幣。奧里克·燧衛把這句話留在鎮外·古地城入口。","flaw":"把「不會吧」三個字記成債。奧里克·燧衛把這句話留在鎮外·古地城入口。","chapters":[{"title":"多出來的那一個","text":"礦道入口，奧里克剛撤出整班礦工，名冊卻比進去時多了一個名字，而且每個人都記得那名不存在的同伴"},{"title":"泊在岸邊","text":"有一個人的夢泊在岸邊，身體在鎮上照常過日子。奧里克·燧衛去看了那個「身體」：買菜、點頭、付錢，就是不叫任何人的名字。奧里克·燧衛叫了他的名字三次。第三次，那人哭了，自己不知道為什麼。"},{"title":"一百五十七","text":"神父寫第一百五十七封信的時候，奧里克·燧衛在旁邊，替那個名字補了一句別人不知道的事：左撇子、怕狗、欠奧里克·燧衛一頓飯。神父一字不改地寫了進去。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。奧里克·燧衛認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。奧里克·燧衛給了她其中一個筆畫"}]}},{"id":"elowen_mirrorfox","story":{"quote":"「不見了」和「死了」是兩件事。前者還欠人一個答案。艾洛溫·鏡狐把這句話留在橡木鎮·醉龍旅店。","ideal":"先數，再找。艾洛溫·鏡狐把這句話留在橡木鎮·醉龍旅店。","bond":"十七個名字裡的一個。不說是誰。艾洛溫·鏡狐把這句話留在橡木鎮·醉龍旅店。","flaw":"認得出名字，卻不願說出是哪一個。艾洛溫·鏡狐把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"多出來的那一個","text":"旅店收藏的老肖像前，艾洛溫指出畫中多了一個不屬於原作的人影，而那張臉和三名失蹤旅客都很相似"},{"title":"同一張桌","text":"阿嘉莎的廚房只有一張桌，那晚擠了十一個人。艾洛溫·鏡狐把自己手上那件怪事放上去——做肖像鑑識師才看得出來的那種——然後聽別人的。十一件事拼起來，是同一條巷子。"},{"title":"第二盞燈","text":"點名到第十七個，山上那第二盞燈亮了一下。艾洛溫·鏡狐看見了。艾洛溫·鏡狐沒有說「他回來了」，也沒有說「他走了」，只是把肖像鑑識師的事做完，然後三年來第一次睡了整夜。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。艾洛溫·鏡狐認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。艾洛溫·鏡狐給了她其中一個筆畫"}]}},{"id":"aislinn_mummerveil","story":{"quote":"數到十六的時候我停了很久。第十七個是我認識的。艾絲琳·扮面把這句話留在橡木鎮·後巷。","ideal":"替還沒回來的人留一個位子。艾絲琳·扮面把這句話留在橡木鎮·後巷。","bond":"阿嘉莎的廚房桌——第一次把所有怪事放在同一張桌上的地方。艾絲琳·扮面把這句話留在橡木鎮·後巷。","flaw":"點名時會停太久。艾絲琳·扮面把這句話留在橡木鎮·後巷。","chapters":[{"title":"多出來的那一個","text":"後巷的排演場，艾絲琳的劇團少了一名團員，所有人卻都記得他今天上過台；只有那副本該由他戴的面具還留在架上，內側全是新的指痕"},{"title":"第三年","text":"艾絲琳·扮面翻出三年前的紀錄。那時她在橡木鎮·後巷，有人說少了一個人，艾絲琳·扮面說「不會吧」。這次艾絲琳·扮面把那一頁撕下來，釘在名單旁邊。"},{"title":"留著","text":"鎮慢慢學會沒有熔爐的日子。艾絲琳·扮面的橡木鎮·後巷留著一個位子、一只碗、一行名字。有人問為什麼不收起來。艾絲琳·扮面說：不見了和死了是兩件事。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。艾絲琳·扮面認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。艾絲琳·扮面給了她其中一個筆畫"}]}},{"id":"garrett_wolfsign","story":{"quote":"我不替誰哭。我替誰點名。蓋瑞特·狼痕把這句話留在橡木鎮·醉龍旅店。","ideal":"名字比消息重要。蓋瑞特·狼痕把這句話留在橡木鎮·醉龍旅店。","bond":"那枚刻著名字、摸上去還有體溫的金幣。蓋瑞特·狼痕把這句話留在橡木鎮·醉龍旅店。","flaw":"等一個人等到不肯聽「別等了」。蓋瑞特·狼痕把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"多出來的那一個","text":"邊境旅店裡，蓋瑞特把一紙高額懸賞推到你面前；畫像每隔一小時就換一張臉，只有眼中的求救神情始終相同"},{"title":"相信","text":"那個孩子說他看見了那條巷子。三年來沒人信。蓋瑞特·狼痕蹲下來，用荒野懸賞追獵人的方式問了三個只有真的看見過的人才答得出的問題。孩子全答對了。蓋瑞特·狼痕站起來說：帶我去。"},{"title":"在","text":"冬至前夜，碑語史家唸到那個名字。蓋瑞特·狼痕站出來，說「在」。替他答的。神殿前庭很冷，沒有人動。回到橡木鎮·醉龍旅店之後，蓋瑞特·狼痕把那個名字寫在自己每天最先看見的地方。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。蓋瑞特·狼痕認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。蓋瑞特·狼痕給了她其中一個筆畫"}]}},{"id":"nomiki_steeproot","story":{"quote":"等一個人最難的不是等，是別人叫你別等了。諾米琪·浸根把這句話留在橡木鎮·市集廣場。","ideal":"把不見的人留下來。諾米琪·浸根把這句話留在橡木鎮·市集廣場。","bond":"十七個名字裡的一個。不說是誰。諾米琪·浸根把這句話留在橡木鎮·市集廣場。","flaw":"把「不會吧」三個字記成債。諾米琪·浸根把這句話留在橡木鎮·市集廣場。","chapters":[{"title":"多出來的那一個","text":"廣場角落，諾米琪指出最近有人每晚收購同一種只用於掩蓋屍臭的乾草，而買主每次都留下不同的名字"},{"title":"泊在岸邊","text":"有一個人的夢泊在岸邊，身體在鎮上照常過日子。諾米琪·浸根去看了那個「身體」：買菜、點頭、付錢，就是不叫任何人的名字。諾米琪·浸根叫了她的名字三次。第三次，那人哭了，自己不知道為什麼。"},{"title":"一百五十七","text":"神父寫第一百五十七封信的時候，諾米琪·浸根在旁邊，替那個名字補了一句別人不知道的事：左撇子、怕狗、欠諾米琪·浸根一頓飯。神父一字不改地寫了進去。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。諾米琪·浸根認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。諾米琪·浸根給了她其中一個筆畫"}]}},{"id":"winnora_dreamferry","story":{"quote":"名字被磨掉的碑，底下的石頭還記得筆畫。人也一樣。溫諾菈·夢渡把這句話留在鎮外·湖畔。","ideal":"先數，再找。溫諾菈·夢渡把這句話留在鎮外·湖畔。","bond":"阿嘉莎的廚房桌——第一次把所有怪事放在同一張桌上的地方。溫諾菈·夢渡把這句話留在鎮外·湖畔。","flaw":"認得出名字，卻不願說出是哪一個。溫諾菈·夢渡把這句話留在鎮外·湖畔。","chapters":[{"title":"多出來的那一個","text":"湖畔碼頭，溫諾菈少了一名乘客；那人的夢還泊在岸邊，身體卻已在鎮上照常過了三天日子"},{"title":"同一張桌","text":"阿嘉莎的廚房只有一張桌，那晚擠了十一個人。溫諾菈·夢渡把自己手上那件怪事放上去——做夢渡引路人才看得出來的那種——然後聽別人的。十一件事拼起來，是同一條巷子。"},{"title":"第二盞燈","text":"點名到第十七個，山上那第二盞燈亮了一下。溫諾菈·夢渡看見了。溫諾菈·夢渡沒有說「他回來了」，也沒有說「他走了」，只是把夢渡引路人的事做完，然後三年來第一次睡了整夜。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。溫諾菈·夢渡認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。溫諾菈·夢渡給了她其中一個筆畫"}]}},{"id":"ogden_kindchalk","story":{"quote":"「不會吧」——我說過這三個字。從那天起我不再說。奧格登·善筆把這句話留在鎮廣場·書樓。","ideal":"替還沒回來的人留一個位子。奧格登·善筆把這句話留在鎮廣場·書樓。","bond":"那枚刻著名字、摸上去還有體溫的金幣。奧格登·善筆把這句話留在鎮廣場·書樓。","flaw":"點名時會停太久。奧格登·善筆把這句話留在鎮廣場·書樓。","chapters":[{"title":"多出來的那一個","text":"書樓的自習區，工匠奧格登正把同一段講第五遍給一名旅人聽，抬頭對你說：這孩子看見了那條走廊，可是沒人相信他"},{"title":"第三年","text":"奧格登·善筆翻出三年前的紀錄。那時他在鎮廣場·書樓，有人說少了一個人，奧格登·善筆說「不會吧」。這次奧格登·善筆把那一頁撕下來，釘在名單旁邊。"},{"title":"留著","text":"鎮慢慢學會沒有熔爐的日子。奧格登·善筆的鎮廣場·書樓留著一個位子、一只碗、一行名字。有人問為什麼不收起來。奧格登·善筆說：不見了和死了是兩件事。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。奧格登·善筆認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。奧格登·善筆給了她其中一個筆畫"}]}},{"id":"sunniva_hearthfeast","story":{"quote":"「不見了」和「死了」是兩件事。前者還欠人一個答案。桑妮娃·灶宴把這句話留在鎮廣場·灶屋。","ideal":"名字比消息重要。桑妮娃·灶宴把這句話留在鎮廣場·灶屋。","bond":"十七個名字裡的一個。不說是誰。桑妮娃·灶宴把這句話留在鎮廣場·灶屋。","flaw":"等一個人等到不肯聽「別等了」。桑妮娃·灶宴把這句話留在鎮廣場·灶屋。","chapters":[{"title":"多出來的那一個","text":"灶屋裡，桑妮娃為節慶大宴多備了四十份餐點，因為她的陶罐連續三晚自行加熱；罐蓋上出現一行請求，要她替「還在等開飯的那一桌」留位"},{"title":"相信","text":"那個孩子說他看見了那條巷子。三年來沒人信。桑妮娃·灶宴蹲下來，用節慶大宴司膳的方式問了三個只有真的看見過的人才答得出的問題。孩子全答對了。桑妮娃·灶宴站起來說：帶我去。"},{"title":"在","text":"冬至前夜，碑語史家唸到那個名字。桑妮娃·灶宴站出來，說「在」。替她答的。神殿前庭很冷，沒有人動。回到鎮廣場·灶屋之後，桑妮娃·灶宴把那個名字寫在自己每天最先看見的地方。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。桑妮娃·灶宴認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。桑妮娃·灶宴給了她其中一個筆畫"}]}},{"id":"maudra_pepperbanner","story":{"quote":"數到十六的時候我停了很久。第十七個是我認識的。茉德菈·椒旗把這句話留在橡木鎮·公會會館。","ideal":"把不見的人留下來。茉德菈·椒旗把這句話留在橡木鎮·公會會館。","bond":"阿嘉莎的廚房桌——第一次把所有怪事放在同一張桌上的地方。茉德菈·椒旗把這句話留在橡木鎮·公會會館。","flaw":"把「不會吧」三個字記成債。茉德菈·椒旗把這句話留在橡木鎮·公會會館。","chapters":[{"title":"多出來的那一個","text":"廚師公會宴席前，茉德菈的百人鍋無論添多少食材都只剩九十九份，彷彿有位看不見的客人已先坐下"},{"title":"泊在岸邊","text":"有一個人的夢泊在岸邊，身體在鎮上照常過日子。茉德菈·椒旗去看了那個「身體」：買菜、點頭、付錢，就是不叫任何人的名字。茉德菈·椒旗叫了她的名字三次。第三次，那人哭了，自己不知道為什麼。"},{"title":"一百五十七","text":"神父寫第一百五十七封信的時候，茉德菈·椒旗在旁邊，替那個名字補了一句別人不知道的事：左撇子、怕狗、欠茉德菈·椒旗一頓飯。神父一字不改地寫了進去。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。茉德菈·椒旗認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。茉德菈·椒旗給了她其中一個筆畫"}]}},{"id":"halvora_quorumstone","story":{"quote":"我不替誰哭。我替誰點名。哈爾芙拉·法定石把這句話留在鎮廣場·功名堂。","ideal":"先數，再找。哈爾芙拉·法定石把這句話留在鎮廣場·功名堂。","bond":"那枚刻著名字、摸上去還有體溫的金幣。哈爾芙拉·法定石把這句話留在鎮廣場·功名堂。","flaw":"認得出名字，卻不願說出是哪一個。哈爾芙拉·法定石把這句話留在鎮廣場·功名堂。","chapters":[{"title":"多出來的那一個","text":"獎盃室的歷屆名冊中，哈爾芙拉找出一名從未畢業卻年年被登記的旅人；今年那欄的簽名墨跡還沒乾"},{"title":"同一張桌","text":"阿嘉莎的廚房只有一張桌，那晚擠了十一個人。哈爾芙拉·法定石把自己手上那件怪事放上去——做學院註冊審核長才看得出來的那種——然後聽別人的。十一件事拼起來，是同一條巷子。"},{"title":"第二盞燈","text":"點名到第十七個，山上那第二盞燈亮了一下。哈爾芙拉·法定石看見了。哈爾芙拉·法定石沒有說「他回來了」，也沒有說「他走了」，只是把學院註冊審核長的事做完，然後三年來第一次睡了整夜。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。哈爾芙拉·法定石認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。哈爾芙拉·法定石給了她其中一個筆畫"}]}},{"id":"mei_lanternwake","story":{"quote":"等一個人最難的不是等，是別人叫你別等了。梅·燈渡把這句話留在鎮外·古地城入口。","ideal":"替還沒回來的人留一個位子。梅·燈渡把這句話留在鎮外·古地城入口。","bond":"十七個名字裡的一個。不說是誰。梅·燈渡把這句話留在鎮外·古地城入口。","flaw":"點名時會停太久。梅·燈渡把這句話留在鎮外·古地城入口。","chapters":[{"title":"多出來的那一個","text":"古地城入口，梅的引魂燈突然熄滅；她說不是沒有亡魂，而是裡面的亡魂全都躲了起來"},{"title":"第三年","text":"梅·燈渡翻出三年前的紀錄。那時她在鎮外·古地城入口，有人說少了一個人，梅·燈渡說「不會吧」。這次梅·燈渡把那一頁撕下來，釘在名單旁邊。"},{"title":"留著","text":"鎮慢慢學會沒有熔爐的日子。梅·燈渡的鎮外·古地城入口留著一個位子、一只碗、一行名字。有人問為什麼不收起來。梅·燈渡說：不見了和死了是兩件事。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。梅·燈渡認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。梅·燈渡給了她其中一個筆畫"}]}},{"id":"agatha","story":{"quote":"名字被磨掉的碑，底下的石頭還記得筆畫。人也一樣。阿嘉莎·織夢把這句話留在橡木鎮·市集廣場。","ideal":"名字比消息重要。阿嘉莎·織夢把這句話留在橡木鎮·市集廣場。","bond":"阿嘉莎的廚房桌——第一次把所有怪事放在同一張桌上的地方。阿嘉莎·織夢把這句話留在橡木鎮·市集廣場。","flaw":"等一個人等到不肯聽「別等了」。阿嘉莎·織夢把這句話留在橡木鎮·市集廣場。","chapters":[{"title":"多出來的那一個","text":"廣場一角的孤兒院門口，阿嘉莎慈祥地給孩子們分糖，抬頭對你溫暖一笑，順手也塞給你一顆"},{"title":"相信","text":"那個孩子說他看見了那條巷子。三年來沒人信。阿嘉莎·織夢蹲下來，用孤兒院院長的方式問了三個只有真的看見過的人才答得出的問題。孩子全答對了。阿嘉莎·織夢站起來說：帶我去。"},{"title":"在","text":"冬至前夜，碑語史家唸到那個名字。阿嘉莎·織夢站出來，說「在」。替她答的。神殿前庭很冷，沒有人動。回到橡木鎮·市集廣場之後，阿嘉莎·織夢把那個名字寫在自己每天最先看見的地方。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。阿嘉莎·織夢認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。阿嘉莎·織夢給了她其中一個筆畫"}]}},{"id":"zibella_opalgrin","story":{"quote":"「不會吧」——我說過這三個字。從那天起我不再說。吉貝拉·歐珀笑把這句話留在橡木鎮·攤販街。","ideal":"把不見的人留下來。吉貝拉·歐珀笑把這句話留在橡木鎮·攤販街。","bond":"那枚刻著名字、摸上去還有體溫的金幣。吉貝拉·歐珀笑把這句話留在橡木鎮·攤販街。","flaw":"把「不會吧」三個字記成債。吉貝拉·歐珀笑把這句話留在橡木鎮·攤販街。","chapters":[{"title":"多出來的那一個","text":"珠寶街上，吉貝拉封起一批新到的蛋白石；每顆石心都困著同一名礦工的微小影像，他正反覆比出求救手勢"},{"title":"泊在岸邊","text":"有一個人的夢泊在岸邊，身體在鎮上照常過日子。吉貝拉·歐珀笑去看了那個「身體」：買菜、點頭、付錢，就是不叫任何人的名字。吉貝拉·歐珀笑叫了她的名字三次。第三次，那人哭了，自己不知道為什麼。"},{"title":"一百五十七","text":"神父寫第一百五十七封信的時候，吉貝拉·歐珀笑在旁邊，替那個名字補了一句別人不知道的事：左撇子、怕狗、欠吉貝拉·歐珀笑一頓飯。神父一字不改地寫了進去。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。吉貝拉·歐珀笑認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。吉貝拉·歐珀笑給了她其中一個筆畫"}]}},{"id":"prism_shutter","story":{"quote":"「不見了」和「死了」是兩件事。前者還欠人一個答案。稜鏡·快門把這句話留在鎮廣場·萬應室。","ideal":"先數，再找。稜鏡·快門把這句話留在鎮廣場·萬應室。","bond":"十七個名字裡的一個。不說是誰。稜鏡·快門把這句話留在鎮廣場·萬應室。","flaw":"認得出名字，卻不願說出是哪一個。稜鏡·快門把這句話留在鎮廣場·萬應室。","chapters":[{"title":"多出來的那一個","text":"萬應室裡，留影師稜鏡舉起黃銅留影匣，遲疑地說她昨夜拍下的影像裡多出了一個沒人站過的位置"},{"title":"同一張桌","text":"阿嘉莎的廚房只有一張桌，那晚擠了十一個人。稜鏡·快門把自己手上那件怪事放上去——做幻術留影師才看得出來的那種——然後聽別人的。十一件事拼起來，是同一條巷子。"},{"title":"第二盞燈","text":"點名到第十七個，山上那第二盞燈亮了一下。稜鏡·快門看見了。稜鏡·快門沒有說「他回來了」，也沒有說「他走了」，只是把幻術留影師的事做完，然後三年來第一次睡了整夜。"}],"relations":[{"id":"gretchen_tithehammer","text":"十七枚刻名的金幣在她手上。稜鏡·快門認得其中一枚上的名字"},{"id":"mara_epitaph","text":"碑上被磨掉的名字，她一筆一筆拓回來。稜鏡·快門給了她其中一個筆畫"}]}},{"id":"theodora_edictbearer","story":{"quote":"印是真的。用印的時間比國王到首都還早。所以我不上台階。","background":"希奧朵菈·詔函的工作是把王詔讀給聽得見的人。她宣讀前必定自己查證。王都的人覺得她笨，笨在不肯把「上面要你讀」當成查證的一種。","ideal":"沒有查過的句子，不借我的聲音。","bond":"一份被她拒絕宣讀的詔書，和三十年畫記的年份對照表。","flaw":"一旦拒絕，就不會給權貴留台階下的面子。","chapters":[{"title":"早了兩天","text":"今晨的王詔要橡木鎮把熔爐的核心交給王都「保管」。印鑑是真的。用印時間比國王抵達首都早了兩天。希奧朵菈把詔書折好，放在台階下面，不是上面。她對傳令說：你可以拿回去。我不讀假的時間。"},{"title":"對照表","text":"畫記官卡蘭希把三十年的授勳畫像年份攤開。同一位伯爵一年年輕一歲，最新的一幅裡他還沒出生。希奧朵菈跟她對了七處跟這份詔書有關的紀錄。七處的墨都比紙年輕。她說：那我們就讀年份。年份不會替誰年輕。"},{"title":"台階上","text":"橡木鎮封印那一夜，王都歌劇院照被銷毀的原稿演出。幕間，希奧朵菈走上她早上不肯上的台階，讀的不是詔書，是對照表。讀完她把詔書還給空座位。第二天伯爵的名字還在所有紀錄裡。這是王都三十年來第一次，有個名字沒有被改年輕，也沒有被抹掉。"}],"relations":[{"id":"calanthe_peacockquill","text":"抓出畫記裡年份的人。對照表是她的，聲音是希奧朵菈的"},{"id":"aveline","text":"同一夜在伯爵晚宴上把密約彈成曲子的樂師"},{"id":"edda","text":"詔書想命令的那個鎮的鎮長。希奧朵菈把拒絕宣讀的副本寄給了她"}]}},{"id":"calanthe_peacockquill","story":{"quote":"我可以畫得很美。我拒絕畫得比事實年輕。","background":"卡蘭希·孔羽在宮廷畫下每一次授勳。她的細膩是職業，她的不肯美化是她唯一不被宮廷原諒的美德。三十年的畫像存在庫房裡，灰塵的厚度比任何詔書誠實。","ideal":"年份、灰塵、筆畫，三樣對不上就不能裝裱。","bond":"三十幅一年年輕一歲的伯爵畫像。她沒有燒，她把年份寫在背面。","flaw":"對精確的驕傲，有時讓她忘了畫裡的人會痛。","chapters":[{"title":"還沒出生","text":"她把三十年的授勳畫像按時間排開，準備做一次例行的裝裱紀錄。排到第十二年她停住。伯爵的臉在變年輕。不是畫師的奉承，是骨骼在退。最新一幅裡，那個位子上的人還沒有出生，禮服卻已經畫好了。"},{"title":"背面","text":"她沒有把這件事寫進會被存檔的報告。報告會被改。她把真實年份寫在每幅畫的背面，字很小，要用同樣的斜光才看得見。詔函官來的時候，她把畫翻過去。兩個人在庫房裡對了整個下午。灰塵落在對照表上，誰也沒有吹。"},{"title":"不裝裱","text":"演出那夜之後，有人來請她把最新的一幅裝裱進大廳。她拒絕。她說：這一幅的人還沒出生。等他出生，如果他還想要這件禮服，讓他自己來坐。伯爵的名字留在畫背面的年份旁邊，沒有被金框吃掉。"}],"relations":[{"id":"theodora_edictbearer","text":"肯把年份讀上臺階的詔函官"},{"id":"vittoria_goldenaria","text":"照被銷毀的原稿唱完全場的歌劇首席。卡蘭希把對照表抄了一份塞進她的譜夾"},{"id":"seraphine_cobblequill","text":"在檔案裡找回被抹掉的工匠街的編年史家。兩個人的證據後來釘在同一本卷宗"}]}},{"id":"feodora_sablecrown","story":{"quote":"我不美化任何一方。這是我唯一的美德，也是我唯一的罪名。","ideal":"被抹掉的街要回到地圖上","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。","flaw":"記得太準，準到讓人不敢把秘密告訴他。費奧朵菈·貂冠把這句話留在橡木鎮·公會藏書閣。","chapters":[{"title":"不對的那一處","text":"公會藏書閣中，費奧朵菈攤開一份未來三年的議會提案；提案筆跡是她自己的，但她昨天才第一次讀到這些內容"},{"title":"十二個老人","text":"瑟拉芬找老居民作證的時候，費奧朵菈·貂冠負責其中三位。三個人分別描述工匠街的路面：灰石、灰石、灰石，中間有一道黃銅的排水槽。沒有串供的可能，他們互不相識。費奧朵菈·貂冠寫下來，簽了自己的名字。"},{"title":"一條虛線","text":"工匠街回到地圖上，一條虛線，註明「待考」。費奧朵菈·貂冠知道那條虛線是誰畫的——是費奧朵菈·貂冠作證的三個老人之一，用他的手杖頭量出來的。費奧朵菈·貂冠回到橡木鎮·公會藏書閣，把自己經手的那份紀錄也加了一條虛線。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。費奧朵菈·貂冠的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。費奧朵菈·貂冠替她對過其中幾幅"}]}},{"id":"canto_vaultwarden","story":{"quote":"權力改得了年份，改不了灰塵落下的厚度。","ideal":"紀錄要比權力活得久。坎托·庫典守把這句話留在橡木鎮·公會會館。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。坎托·庫典守把這句話留在橡木鎮·公會會館。","flaw":"在宴席上沉默得像在記帳。坎托·庫典守把這句話留在橡木鎮·公會會館。","chapters":[{"title":"不對的那一處","text":"公會地庫中，坎托打開一只自行敲門的封存箱，裡面每份檔案都記載同一場被全城遺忘的政變"},{"title":"封存箱","text":"坎托打開那只自己敲門的箱子時，坎托·庫典守在旁邊。檔案記的是一場沒有人記得的政變，日期在八百年前封釘之後第三年。坎托·庫典守讀到一個名字，跟現在的伯爵同姓。"},{"title":"沒有消失","text":"第二天早上，伯爵的名字還在所有紀錄裡。三十年來第一次。坎托·庫典守做公會檔案守衛做了那麼久，第一次覺得這份工作有重量。重量不大，像一枚金幣。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。坎托·庫典守的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。坎托·庫典守替她對過其中幾幅"}]}},{"id":"seraphine_cobblequill","story":{"quote":"照原稿。一個字都不改。這就是我的反抗。","ideal":"不美化任何一方。瑟拉芬·石街羽把這句話留在橡木鎮·公會藏書閣。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。瑟拉芬·石街羽把這句話留在橡木鎮·公會藏書閣。","flaw":"對改過的年份零容忍，對改的人卻懶得給台階。瑟拉芬·石街羽把這句話留在橡木鎮·公會藏書閣。","chapters":[{"title":"不對的那一處","text":"城市檔案館中，瑟拉芬攤開十二名老居民的證詞，他們都記得一條被官方地圖徹底抹去的工匠街"},{"title":"對照表","text":"瑟拉芬·石街羽拿到了卡蘭希的畫記年份對照表，把城市編年史家這些年經手的紀錄一行一行對上去。對不上的地方有七處。七處都跟伯爵有關。瑟拉芬·石街羽把七處抄成一張紙，貼身放著。"},{"title":"座位表","text":"事後有人問起那一夜，瑟拉芬·石街羽只交出一張座位表。誰坐在哪裡、誰在第幾幕離席、誰的酒杯沒有動。瑟拉芬·石街羽說：我不下結論，我只記座位。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。瑟拉芬·石街羽的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。瑟拉芬·石街羽替她對過其中幾幅"}]}},{"id":"darian_crownsunder","story":{"quote":"他們抹掉一條街的時候，忘了街上住的人會老，老人會說話。","ideal":"原稿一個字都不改。達里安·裂冠把這句話留在鎮廣場·書樓。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。達里安·裂冠把這句話留在鎮廣場·書樓。","flaw":"把座位表看得比口供重。達里安·裂冠把這句話留在鎮廣場·書樓。","chapters":[{"title":"不對的那一處","text":"書樓裡，達里安把三本校史疊在一起，證明它們都刻意刪去同一位地底建築師；那人的簽名昨夜出現在你的房門內側"},{"title":"晚宴","text":"伯爵的晚宴，達里安·裂冠在場——做失落王朝罪案史家的人在那種場合通常沒有人看。達里安·裂冠看見樂師彈了什麼、試毒官的臉色、彩窗變成什麼顏色。達里安·裂冠什麼都沒說，只是記住了座位表。"},{"title":"原稿","text":"維多莉雅照原稿演完，後台沒有人說話。達里安·裂冠把自己那份——失落王朝罪案史家的那份原稿——交給了她：「妳下次演這個。」然後回了橡木鎮。王都的事沒有結束，但這一次有了底稿。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。達里安·裂冠的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。達里安·裂冠替她對過其中幾幅"}]}},{"id":"vittoria_goldenaria","story":{"quote":"紀錄不會說謊。改紀錄的人才會。維多莉雅·金詠把這句話留在橡木鎮·醉龍旅店。","ideal":"被抹掉的街要回到地圖上。維多莉雅·金詠把這句話留在橡木鎮·醉龍旅店。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。維多莉雅·金詠把這句話留在橡木鎮·醉龍旅店。","flaw":"記得太準，準到讓人不敢把秘密告訴他。維多莉雅·金詠把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"不對的那一處","text":"醉龍旅店二樓，維多莉雅遞給你一份被官方銷毀的劇本；她今晚要照原稿演出，但需要有人確認觀眾席那位「贊助人」到底受誰指使"},{"title":"十二個老人","text":"瑟拉芬找老居民作證的時候，維多莉雅·金詠負責其中三位。三個人分別描述工匠街的路面：灰石、灰石、灰石，中間有一道黃銅的排水槽。沒有串供的可能，他們互不相識。維多莉雅·金詠寫下來，簽了自己的名字。"},{"title":"一條虛線","text":"工匠街回到地圖上，一條虛線，註明「待考」。維多莉雅·金詠知道那條虛線是誰畫的——是維多莉雅·金詠作證的三個老人之一，用他的手杖頭量出來的。維多莉雅·金詠回到橡木鎮·醉龍旅店，把自己經手的那份紀錄也加了一條虛線。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。維多莉雅·金詠的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。維多莉雅·金詠替她對過其中幾幅"}]}},{"id":"theren_quillmask","story":{"quote":"在王都，最危險的不是知道太多，是記得太準。瑟倫·羽面把這句話留在橡木鎮·醉龍旅店。","ideal":"紀錄要比權力活得久。瑟倫·羽面把這句話留在橡木鎮·醉龍旅店。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。瑟倫·羽面把這句話留在橡木鎮·醉龍旅店。","flaw":"在宴席上沉默得像在記帳。瑟倫·羽面把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"不對的那一處","text":"酒館後台，瑟倫新寫的暴君每晚都從劇本刪掉一名角色；昨夜消失的角色所影射的議員，今晨也失蹤了"},{"title":"封存箱","text":"坎托打開那只自己敲門的箱子時，瑟倫·羽面在旁邊。檔案記的是一場沒有人記得的政變，日期在八百年前封釘之後第三年。瑟倫·羽面讀到一個名字，跟現在的伯爵同姓。"},{"title":"沒有消失","text":"第二天早上，伯爵的名字還在所有紀錄裡。三十年來第一次。瑟倫·羽面做諷刺劇作家做了那麼久，第一次覺得這份工作有重量。重量不大，像一枚金幣。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。瑟倫·羽面的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。瑟倫·羽面替她對過其中幾幅"}]}},{"id":"pellonia_featherwrit","story":{"quote":"我不美化任何一方。這是我唯一的美德，也是我唯一的罪名。珮蘿妮亞·羽書把這句話留在橡木鎮·公會藏書閣。","ideal":"不美化任何一方。珮蘿妮亞·羽書把這句話留在橡木鎮·公會藏書閣。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。珮蘿妮亞·羽書把這句話留在橡木鎮·公會藏書閣。","flaw":"對改過的年份零容忍，對改的人卻懶得給台階。珮蘿妮亞·羽書把這句話留在橡木鎮·公會藏書閣。","chapters":[{"title":"不對的那一處","text":"藏書閣抄寫間，珮蘿妮亞發現三本神諭抄本被人抹去同一段落；她用借來的嗓音複誦出原文，字句指向一座已被官方宣告不存在的神殿"},{"title":"對照表","text":"珮蘿妮亞·羽書拿到了卡蘭希的畫記年份對照表，把天諭抄錄使這些年經手的紀錄一行一行對上去。對不上的地方有七處。七處都跟伯爵有關。珮蘿妮亞·羽書把七處抄成一張紙，貼身放著。"},{"title":"座位表","text":"事後有人問起那一夜，珮蘿妮亞·羽書只交出一張座位表。誰坐在哪裡、誰在第幾幕離席、誰的酒杯沒有動。珮蘿妮亞·羽書說：我不下結論，我只記座位。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。珮蘿妮亞·羽書的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。珮蘿妮亞·羽書替她對過其中幾幅"}]}},{"id":"aelric_verdechef","story":{"quote":"權力改得了年份，改不了灰塵落下的厚度。艾爾里克·翠宴把這句話留在橡木鎮·醉龍旅店。","ideal":"原稿一個字都不改。艾爾里克·翠宴把這句話留在橡木鎮·醉龍旅店。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。艾爾里克·翠宴把這句話留在橡木鎮·醉龍旅店。","flaw":"把座位表看得比口供重。艾爾里克·翠宴把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"不對的那一處","text":"醉龍旅店的後廚，艾爾里克放下刀審視地看你一眼，說這間店的食材來源他查過了，其中一項有問題"},{"title":"晚宴","text":"伯爵的晚宴，艾爾里克·翠宴在場——做御廚的人在那種場合通常沒有人看。艾爾里克·翠宴看見樂師彈了什麼、試毒官的臉色、彩窗變成什麼顏色。艾爾里克·翠宴什麼都沒說，只是記住了座位表。"},{"title":"原稿","text":"維多莉雅照原稿演完，後台沒有人說話。艾爾里克·翠宴把自己那份——御廚的那份原稿——交給了她：「妳下次演這個。」然後回了橡木鎮。王都的事沒有結束，但這一次有了底稿。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。艾爾里克·翠宴的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。艾爾里克·翠宴替她對過其中幾幅"}]}},{"id":"wrenna_cupbearer","story":{"quote":"照原稿。一個字都不改。這就是我的反抗。芮娜·執杯把這句話留在橡木鎮·醉龍旅店。","ideal":"被抹掉的街要回到地圖上。芮娜·執杯把這句話留在橡木鎮·醉龍旅店。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。芮娜·執杯把這句話留在橡木鎮·醉龍旅店。","flaw":"記得太準，準到讓人不敢把秘密告訴他。芮娜·執杯把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"不對的那一處","text":"醉龍旅店的貴賓宴上，芮娜試出一種在飲者說謊時才會發作的毒；她需要有人陪她找出下毒者，因為那人顯然只想聽真話"},{"title":"十二個老人","text":"瑟拉芬找老居民作證的時候，芮娜·執杯負責其中三位。三個人分別描述工匠街的路面：灰石、灰石、灰石，中間有一道黃銅的排水槽。沒有串供的可能，他們互不相識。芮娜·執杯寫下來，簽了自己的名字。"},{"title":"一條虛線","text":"工匠街回到地圖上，一條虛線，註明「待考」。芮娜·執杯知道那條虛線是誰畫的——是芮娜·執杯作證的三個老人之一，用他的手杖頭量出來的。芮娜·執杯回到橡木鎮·醉龍旅店，把自己經手的那份紀錄也加了一條虛線。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。芮娜·執杯的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。芮娜·執杯替她對過其中幾幅"}]}},{"id":"ondine_courtmirror","story":{"quote":"他們抹掉一條街的時候，忘了街上住的人會老，老人會說話。昂汀·廷鏡把這句話留在橡木鎮·市集廣場。","ideal":"紀錄要比權力活得久。昂汀·廷鏡把這句話留在橡木鎮·市集廣場。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。昂汀·廷鏡把這句話留在橡木鎮·市集廣場。","flaw":"在宴席上沉默得像在記帳。昂汀·廷鏡把這句話留在橡木鎮·市集廣場。","chapters":[{"title":"不對的那一處","text":"市集廣場的迎賓台上，昂汀請你當她的副手：今晚的外邦使團有兩位自稱同一人，而依禮節她不能當面質疑任何一方"},{"title":"封存箱","text":"坎托打開那只自己敲門的箱子時，昂汀·廷鏡在旁邊。檔案記的是一場沒有人記得的政變，日期在八百年前封釘之後第三年。昂汀·廷鏡讀到一個名字，跟現在的伯爵同姓。"},{"title":"沒有消失","text":"第二天早上，伯爵的名字還在所有紀錄裡。三十年來第一次。昂汀·廷鏡做宮廷禮儀鏡官做了那麼久，第一次覺得這份工作有重量。重量不大，像一枚金幣。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。昂汀·廷鏡的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。昂汀·廷鏡替她對過其中幾幅"}]}},{"id":"elian_greenbow","story":{"quote":"紀錄不會說謊。改紀錄的人才會。艾利安·翠弦把這句話留在橡木鎮·醉龍旅店。","ideal":"不美化任何一方。艾利安·翠弦把這句話留在橡木鎮·醉龍旅店。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。艾利安·翠弦把這句話留在橡木鎮·醉龍旅店。","flaw":"對改過的年份零容忍，對改的人卻懶得給台階。艾利安·翠弦把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"不對的那一處","text":"醉龍旅店的爐火邊，艾利安收起琴弓向你致意，溫和地說這間店的迴聲最近變了，他懷疑地下多了空腔"},{"title":"對照表","text":"艾利安·翠弦拿到了卡蘭希的畫記年份對照表，把宮廷小提琴家這些年經手的紀錄一行一行對上去。對不上的地方有七處。七處都跟伯爵有關。艾利安·翠弦把七處抄成一張紙，貼身放著。"},{"title":"座位表","text":"事後有人問起那一夜，艾利安·翠弦只交出一張座位表。誰坐在哪裡、誰在第幾幕離席、誰的酒杯沒有動。艾利安·翠弦說：我不下結論，我只記座位。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。艾利安·翠弦的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。艾利安·翠弦替她對過其中幾幅"}]}},{"id":"belisent_glassminuet","story":{"quote":"在王都，最危險的不是知道太多，是記得太準。貝莉森·璃步把這句話留在橡木鎮·傭兵訓練場。","ideal":"原稿一個字都不改。貝莉森·璃步把這句話留在橡木鎮·傭兵訓練場。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。貝莉森·璃步把這句話留在橡木鎮·傭兵訓練場。","flaw":"把座位表看得比口供重。貝莉森·璃步把這句話留在橡木鎮·傭兵訓練場。","chapters":[{"title":"不對的那一處","text":"傭兵訓練場旁的舞儀課上，貝莉森的銀鈴環自行加快半拍；她說有人正在鎮上另一處以同一支曲子跳舞，而那支曲子專門用來計時"},{"title":"晚宴","text":"伯爵的晚宴，貝莉森·璃步在場——做宮廷舞儀教習的人在那種場合通常沒有人看。貝莉森·璃步看見樂師彈了什麼、試毒官的臉色、彩窗變成什麼顏色。貝莉森·璃步什麼都沒說，只是記住了座位表。"},{"title":"原稿","text":"維多莉雅照原稿演完，後台沒有人說話。貝莉森·璃步把自己那份——宮廷舞儀教習的那份原稿——交給了她：「妳下次演這個。」然後回了橡木鎮。王都的事沒有結束，但這一次有了底稿。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。貝莉森·璃步的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。貝莉森·璃步替她對過其中幾幅"}]}},{"id":"sylphra_ribbonvault","story":{"quote":"我不美化任何一方。這是我唯一的美德，也是我唯一的罪名。希爾芙菈·緞穹把這句話留在橡木鎮·醉龍旅店。","ideal":"被抹掉的街要回到地圖上。希爾芙菈·緞穹把這句話留在橡木鎮·醉龍旅店。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。希爾芙菈·緞穹把這句話留在橡木鎮·醉龍旅店。","flaw":"記得太準，準到讓人不敢把秘密告訴他。希爾芙菈·緞穹把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"不對的那一處","text":"劇院酒館的高架上，希爾芙菈發現安全索被繫上一個完美陌生結；繩端穿過屋頂，吊著一把仍滴雨的王宮鑰匙"},{"title":"十二個老人","text":"瑟拉芬找老居民作證的時候，希爾芙菈·緞穹負責其中三位。三個人分別描述工匠街的路面：灰石、灰石、灰石，中間有一道黃銅的排水槽。沒有串供的可能，他們互不相識。希爾芙菈·緞穹寫下來，簽了自己的名字。"},{"title":"一條虛線","text":"工匠街回到地圖上，一條虛線，註明「待考」。希爾芙菈·緞穹知道那條虛線是誰畫的——是希爾芙菈·緞穹作證的三個老人之一，用他的手杖頭量出來的。希爾芙菈·緞穹回到橡木鎮·醉龍旅店，把自己經手的那份紀錄也加了一條虛線。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。希爾芙菈·緞穹的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。希爾芙菈·緞穹替她對過其中幾幅"}]}},{"id":"hark_finesew","story":{"quote":"權力改得了年份，改不了灰塵落下的厚度。哈克·巧縫把這句話留在鎮廣場·議事廳。","ideal":"紀錄要比權力活得久。哈克·巧縫把這句話留在鎮廣場·議事廳。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。哈克·巧縫把這句話留在鎮廣場·議事廳。","flaw":"在宴席上沉默得像在記帳。哈克·巧縫把這句話留在鎮廣場·議事廳。","chapters":[{"title":"不對的那一處","text":"議事廳旁的更衣間，裁縫哈克一眼就報出你去年的尺寸，隨即皺眉說有件校袍被人改過內襯，縫法不是他的"},{"title":"封存箱","text":"坎托打開那只自己敲門的箱子時，哈克·巧縫在旁邊。檔案記的是一場沒有人記得的政變，日期在八百年前封釘之後第三年。哈克·巧縫讀到一個名字，跟現在的伯爵同姓。"},{"title":"沒有消失","text":"第二天早上，伯爵的名字還在所有紀錄裡。三十年來第一次。哈克·巧縫做高級裁縫做了那麼久，第一次覺得這份工作有重量。重量不大，像一枚金幣。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。哈克·巧縫的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。哈克·巧縫替她對過其中幾幅"}]}},{"id":"opal_manyfaces","story":{"quote":"照原稿。一個字都不改。這就是我的反抗。歐珀·百面把這句話留在鎮廣場·議事廳。","ideal":"不美化任何一方。歐珀·百面把這句話留在鎮廣場·議事廳。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。歐珀·百面把這句話留在鎮廣場·議事廳。","flaw":"對改過的年份零容忍，對改的人卻懶得給台階。歐珀·百面把這句話留在鎮廣場·議事廳。","chapters":[{"title":"不對的那一處","text":"議事廳的更衣側間，戲服師歐珀看你走了兩步便說出你的尺寸，接著壓低聲音：昨天有人來訂一套「不想被認出來」的行頭"},{"title":"對照表","text":"歐珀·百面拿到了卡蘭希的畫記年份對照表，把戲服設計師這些年經手的紀錄一行一行對上去。對不上的地方有七處。七處都跟伯爵有關。歐珀·百面把七處抄成一張紙，貼身放著。"},{"title":"座位表","text":"事後有人問起那一夜，歐珀·百面只交出一張座位表。誰坐在哪裡、誰在第幾幕離席、誰的酒杯沒有動。歐珀·百面說：我不下結論，我只記座位。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。歐珀·百面的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。歐珀·百面替她對過其中幾幅"}]}},{"id":"grixa_stagecall","story":{"quote":"他們抹掉一條街的時候，忘了街上住的人會老，老人會說話。格莉莎·開幕把這句話留在鎮廣場·議事廳。","ideal":"原稿一個字都不改。格莉莎·開幕把這句話留在鎮廣場·議事廳。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。格莉莎·開幕把這句話留在鎮廣場·議事廳。","flaw":"把座位表看得比口供重。格莉莎·開幕把這句話留在鎮廣場·議事廳。","chapters":[{"title":"不對的那一處","text":"議事廳改成的臨時劇場裡，導演格莉莎的吼聲響徹全場，罵完才轉向你說：有個演員照著劇本走位，卻走進了一道不存在的側門"},{"title":"晚宴","text":"伯爵的晚宴，格莉莎·開幕在場——做劇場導演的人在那種場合通常沒有人看。格莉莎·開幕看見樂師彈了什麼、試毒官的臉色、彩窗變成什麼顏色。格莉莎·開幕什麼都沒說，只是記住了座位表。"},{"title":"原稿","text":"維多莉雅照原稿演完，後台沒有人說話。格莉莎·開幕把自己那份——劇場導演的那份原稿——交給了她：「妳下次演這個。」然後回了橡木鎮。王都的事沒有結束，但這一次有了底稿。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。格莉莎·開幕的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。格莉莎·開幕替她對過其中幾幅"}]}},{"id":"roland_mirthmantle","story":{"quote":"紀錄不會說謊。改紀錄的人才會。羅蘭·歡幕把這句話留在鎮廣場·議事廳。","ideal":"被抹掉的街要回到地圖上。羅蘭·歡幕把這句話留在鎮廣場·議事廳。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。羅蘭·歡幕把這句話留在鎮廣場·議事廳。","flaw":"記得太準，準到讓人不敢把秘密告訴他。羅蘭·歡幕把這句話留在鎮廣場·議事廳。","chapters":[{"title":"不對的那一處","text":"議事廳排戲時，羅蘭隨口杜撰的陌生國王竟從牆上肖像裡回話，還準確說出鎮上地基下的王陵位置"},{"title":"十二個老人","text":"瑟拉芬找老居民作證的時候，羅蘭·歡幕負責其中三位。三個人分別描述工匠街的路面：灰石、灰石、灰石，中間有一道黃銅的排水槽。沒有串供的可能，他們互不相識。羅蘭·歡幕寫下來，簽了自己的名字。"},{"title":"一條虛線","text":"工匠街回到地圖上，一條虛線，註明「待考」。羅蘭·歡幕知道那條虛線是誰畫的——是羅蘭·歡幕作證的三個老人之一，用他的手杖頭量出來的。羅蘭·歡幕回到鎮廣場·議事廳，把自己經手的那份紀錄也加了一條虛線。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。羅蘭·歡幕的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。羅蘭·歡幕替她對過其中幾幅"}]}},{"id":"samira_goldvoice","story":{"quote":"在王都，最危險的不是知道太多，是記得太準。薩米菈·金語把這句話留在橡木鎮·晨光神殿。","ideal":"紀錄要比權力活得久。薩米菈·金語把這句話留在橡木鎮·晨光神殿。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。薩米菈·金語把這句話留在橡木鎮·晨光神殿。","flaw":"在宴席上沉默得像在記帳。薩米菈·金語把這句話留在橡木鎮·晨光神殿。","chapters":[{"title":"不對的那一處","text":"晨光神殿的接待廳，薩米菈遞來一卷未拆的文書，從容地說有兩個派系都想用你，她建議你先聽完條件"},{"title":"封存箱","text":"坎托打開那只自己敲門的箱子時，薩米菈·金語在旁邊。檔案記的是一場沒有人記得的政變，日期在八百年前封釘之後第三年。薩米菈·金語讀到一個名字，跟現在的伯爵同姓。"},{"title":"沒有消失","text":"第二天早上，伯爵的名字還在所有紀錄裡。三十年來第一次。薩米菈·金語做城邦大使做了那麼久，第一次覺得這份工作有重量。重量不大，像一枚金幣。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。薩米菈·金語的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。薩米菈·金語替她對過其中幾幅"}]}},{"id":"pax_quietwhisker","story":{"quote":"我不美化任何一方。這是我唯一的美德，也是我唯一的罪名。帕克斯·靜鬚把這句話留在橡木鎮·後巷。","ideal":"不美化任何一方。帕克斯·靜鬚把這句話留在橡木鎮·後巷。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。帕克斯·靜鬚把這句話留在橡木鎮·後巷。","flaw":"對改過的年份零容忍，對改的人卻懶得給台階。帕克斯·靜鬚把這句話留在橡木鎮·後巷。","chapters":[{"title":"不對的那一處","text":"後巷屋簷下，帕克斯說全城乞兒同時夢見一名沒有影子的貴族，而那人今日正要加入市議會"},{"title":"對照表","text":"帕克斯·靜鬚拿到了卡蘭希的畫記年份對照表，把市井消息掮客這些年經手的紀錄一行一行對上去。對不上的地方有七處。七處都跟伯爵有關。帕克斯·靜鬚把七處抄成一張紙，貼身放著。"},{"title":"座位表","text":"事後有人問起那一夜，帕克斯·靜鬚只交出一張座位表。誰坐在哪裡、誰在第幾幕離席、誰的酒杯沒有動。帕克斯·靜鬚說：我不下結論，我只記座位。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。帕克斯·靜鬚的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。帕克斯·靜鬚替她對過其中幾幅"}]}},{"id":"lucrecia_velvetaccord","story":{"quote":"權力改得了年份，改不了灰塵落下的厚度。露克瑞希雅·絨約把這句話留在橡木鎮·醉龍旅店。","ideal":"原稿一個字都不改。露克瑞希雅·絨約把這句話留在橡木鎮·醉龍旅店。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。露克瑞希雅·絨約把這句話留在橡木鎮·醉龍旅店。","flaw":"把座位表看得比口供重。露克瑞希雅·絨約把這句話留在橡木鎮·醉龍旅店。","chapters":[{"title":"不對的那一處","text":"醉龍旅店包廂裡，露克瑞希雅把兩份互為鏡像的和約推到桌上；兩份都是真跡，兩份都說對方須先撤軍，而她只有一夜找出插入條文的第三方"},{"title":"晚宴","text":"伯爵的晚宴，露克瑞希雅·絨約在場——做條約絨印特使的人在那種場合通常沒有人看。露克瑞希雅·絨約看見樂師彈了什麼、試毒官的臉色、彩窗變成什麼顏色。露克瑞希雅·絨約什麼都沒說，只是記住了座位表。"},{"title":"原稿","text":"維多莉雅照原稿演完，後台沒有人說話。露克瑞希雅·絨約把自己那份——條約絨印特使的那份原稿——交給了她：「妳下次演這個。」然後回了橡木鎮。王都的事沒有結束，但這一次有了底稿。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。露克瑞希雅·絨約的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。露克瑞希雅·絨約替她對過其中幾幅"}]}},{"id":"kirrena_truceweave","story":{"quote":"照原稿。一個字都不改。這就是我的反抗。綺蕾娜·和織把這句話留在橡木鎮·公會藏書閣。","ideal":"被抹掉的街要回到地圖上。綺蕾娜·和織把這句話留在橡木鎮·公會藏書閣。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。綺蕾娜·和織把這句話留在橡木鎮·公會藏書閣。","flaw":"記得太準，準到讓人不敢把秘密告訴他。綺蕾娜·和織把這句話留在橡木鎮·公會藏書閣。","chapters":[{"title":"不對的那一處","text":"公會藏書閣議事桌前，綺蕾娜低聲告訴你：今天的和談雙方，說的是同一套只有她聽得懂的暗語，而暗語內容是如何一起吞下你們的委託人"},{"title":"十二個老人","text":"瑟拉芬找老居民作證的時候，綺蕾娜·和織負責其中三位。三個人分別描述工匠街的路面：灰石、灰石、灰石，中間有一道黃銅的排水槽。沒有串供的可能，他們互不相識。綺蕾娜·和織寫下來，簽了自己的名字。"},{"title":"一條虛線","text":"工匠街回到地圖上，一條虛線，註明「待考」。綺蕾娜·和織知道那條虛線是誰畫的——是綺蕾娜·和織作證的三個老人之一，用他的手杖頭量出來的。綺蕾娜·和織回到橡木鎮·公會藏書閣，把自己經手的那份紀錄也加了一條虛線。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。綺蕾娜·和織的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。綺蕾娜·和織替她對過其中幾幅"}]}},{"id":"rosalind_dowerseal","story":{"quote":"他們抹掉一條街的時候，忘了街上住的人會老，老人會說話。蘿莎琳·嫁印把這句話留在橡木鎮·晨光神殿。","ideal":"紀錄要比權力活得久。蘿莎琳·嫁印把這句話留在橡木鎮·晨光神殿。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。蘿莎琳·嫁印把這句話留在橡木鎮·晨光神殿。","flaw":"在宴席上沉默得像在記帳。蘿莎琳·嫁印把這句話留在橡木鎮·晨光神殿。","chapters":[{"title":"不對的那一處","text":"晨光神殿側廊，蘿莎琳拒絕公證一樁貴族聯姻：新娘每次回答都準確重複前一位證人的語調，而她連自己的名字都要看紙條"},{"title":"封存箱","text":"坎托打開那只自己敲門的箱子時，蘿莎琳·嫁印在旁邊。檔案記的是一場沒有人記得的政變，日期在八百年前封釘之後第三年。蘿莎琳·嫁印讀到一個名字，跟現在的伯爵同姓。"},{"title":"沒有消失","text":"第二天早上，伯爵的名字還在所有紀錄裡。三十年來第一次。蘿莎琳·嫁印做聯姻契約公證使做了那麼久，第一次覺得這份工作有重量。重量不大，像一枚金幣。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。蘿莎琳·嫁印的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。蘿莎琳·嫁印替她對過其中幾幅"}]}},{"id":"elysia_frostlace","story":{"quote":"紀錄不會說謊。改紀錄的人才會。艾莉西亞·霜蕾把這句話留在鎮廣場·議事廳。","ideal":"不美化任何一方。艾莉西亞·霜蕾把這句話留在鎮廣場·議事廳。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。艾莉西亞·霜蕾把這句話留在鎮廣場·議事廳。","flaw":"對改過的年份零容忍，對改的人卻懶得給台階。艾莉西亞·霜蕾把這句話留在鎮廣場·議事廳。","chapters":[{"title":"不對的那一處","text":"議事廳的宴會冰雕旁，冰雕師艾莉西亞清冷地說她的作品昨夜自己裂了，裂紋的走向和鎮上東側的牆一模一樣"},{"title":"對照表","text":"艾莉西亞·霜蕾拿到了卡蘭希的畫記年份對照表，把冰雕師這些年經手的紀錄一行一行對上去。對不上的地方有七處。七處都跟伯爵有關。艾莉西亞·霜蕾把七處抄成一張紙，貼身放著。"},{"title":"座位表","text":"事後有人問起那一夜，艾莉西亞·霜蕾只交出一張座位表。誰坐在哪裡、誰在第幾幕離席、誰的酒杯沒有動。艾莉西亞·霜蕾說：我不下結論，我只記座位。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。艾莉西亞·霜蕾的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。艾莉西亞·霜蕾替她對過其中幾幅"}]}},{"id":"cindra_kilnveil","story":{"quote":"在王都，最危險的不是知道太多，是記得太準。辛德菈·窯帷把這句話留在鎮廣場·議事廳。","ideal":"原稿一個字都不改。辛德菈·窯帷把這句話留在鎮廣場·議事廳。","bond":"被地圖抹掉的工匠街。十二個老人還記得它的路面是什麼顏色。辛德菈·窯帷把這句話留在鎮廣場·議事廳。","flaw":"把座位表看得比口供重。辛德菈·窯帷把這句話留在鎮廣場·議事廳。","chapters":[{"title":"不對的那一處","text":"大廳彩窗下，辛德菈指出其中一片玻璃是近百年補上的偽品；它的顏色只在有人說謊時變深，而今晚整片窗已近墨色"},{"title":"晚宴","text":"伯爵的晚宴，辛德菈·窯帷在場——做玻璃符窯匠的人在那種場合通常沒有人看。辛德菈·窯帷看見樂師彈了什麼、試毒官的臉色、彩窗變成什麼顏色。辛德菈·窯帷什麼都沒說，只是記住了座位表。"},{"title":"原稿","text":"維多莉雅照原稿演完，後台沒有人說話。辛德菈·窯帷把自己那份——玻璃符窯匠的那份原稿——交給了她：「妳下次演這個。」然後回了橡木鎮。王都的事沒有結束，但這一次有了底稿。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。辛德菈·窯帷的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。辛德菈·窯帷替她對過其中幾幅"}]}},{"id":"ithanne_truceblade","story":{"quote":"我不美化任何一方。這是我唯一的美德，也是我唯一的罪名。伊珊恩·休戰刃把這句話留在鎮廣場·議事廳。","ideal":"被抹掉的街要回到地圖上。伊珊恩·休戰刃把這句話留在鎮廣場·議事廳。","bond":"伯爵的晚宴那一夜，所有沒有說謊的人。伊珊恩·休戰刃把這句話留在鎮廣場·議事廳。","flaw":"記得太準，準到讓人不敢把秘密告訴他。伊珊恩·休戰刃把這句話留在鎮廣場·議事廳。","chapters":[{"title":"不對的那一處","text":"大廳決鬥台上，伊珊恩喊停一場比賽；兩名旅人使出的招式屬於同一位早已去世的工匠，而兩人都說是在夢裡學的"},{"title":"十二個老人","text":"瑟拉芬找老居民作證的時候，伊珊恩·休戰刃負責其中三位。三個人分別描述工匠街的路面：灰石、灰石、灰石，中間有一道黃銅的排水槽。沒有串供的可能，他們互不相識。伊珊恩·休戰刃寫下來，簽了自己的名字。"},{"title":"一條虛線","text":"工匠街回到地圖上，一條虛線，註明「待考」。伊珊恩·休戰刃知道那條虛線是誰畫的——是伊珊恩·休戰刃作證的三個老人之一，用他的手杖頭量出來的。伊珊恩·休戰刃回到鎮廣場·議事廳，把自己經手的那份紀錄也加了一條虛線。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。伊珊恩·休戰刃的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。伊珊恩·休戰刃替她對過其中幾幅"}]}},{"id":"verda_redbrief","story":{"quote":"權力改得了年份，改不了灰塵落下的厚度。薇爾妲·紅辯把這句話留在橡木鎮·晨光神殿。","ideal":"紀錄要比權力活得久。薇爾妲·紅辯把這句話留在橡木鎮·晨光神殿。","bond":"一份沒有被改過的原稿。不管那是劇本、畫記、帳冊還是詔書。薇爾妲·紅辯把這句話留在橡木鎮·晨光神殿。","flaw":"在宴席上沉默得像在記帳。薇爾妲·紅辯把這句話留在橡木鎮·晨光神殿。","chapters":[{"title":"不對的那一處","text":"晨光神殿的公審廳外，薇爾妲拉住你講起案情，說被告根本不在現場，而唯一的證人拿了錢"},{"title":"封存箱","text":"坎托打開那只自己敲門的箱子時，薇爾妲·紅辯在旁邊。檔案記的是一場沒有人記得的政變，日期在八百年前封釘之後第三年。薇爾妲·紅辯讀到一個名字，跟現在的伯爵同姓。"},{"title":"沒有消失","text":"第二天早上，伯爵的名字還在所有紀錄裡。三十年來第一次。薇爾妲·紅辯做法庭辯護士做了那麼久，第一次覺得這份工作有重量。重量不大，像一枚金幣。"}],"relations":[{"id":"theodora_edictbearer","text":"拒絕宣讀偽詔的詔函官。薇爾妲·紅辯的紀錄是她台階上那份對照表的一行"},{"id":"calanthe_peacockquill","text":"三十年畫記裡抓出年份的畫記官。薇爾妲·紅辯替她對過其中幾幅"}]}},{"id":"cressida_marchwarden","story":{"quote":"邊民的損失不是可接受的代價。找不到，就繼續找。","background":"克蕾希妲·邊巡帶著遊騎在王國邊線上來回。她記得每個部下的名字，也記得名冊上那些按時繳稅、人卻不在地圖上的村子。她拒絕把「失聯」寫成「可接受」。","ideal":"繳了稅的村子就還在。在，就要被找到。","bond":"三座村子。名冊上的名字後來被她描深，旁邊寫：找到了。","flaw":"找到以前，她不會回家，也不會讓部下先回。","chapters":[{"title":"還在繳稅","text":"三座村子按時把稅送進橡木鎮，她的巡騎卻有兩年沒能在地圖上找到它們。稅是真的，糧袋上的縫法也是那些村的女人的針腳。克蕾希妲把名冊攤在城門口，說：人還在付錢。所以人還在。是路不讓我們回去。"},{"title":"手套","text":"他們改了找法。不找村，找路上小孩掉的東西。一隻手套、一段嚼過的草、一道不該那麼新的車轍。克蕾希妲走到村口時，門口的人說：你們終於來了。我們一直記得出發，不記得為什麼要回來。她把手套還給那個孩子。孩子說謝謝。然後問：我媽媽知道我在這裡嗎。"},{"title":"描深","text":"封印之後，村子的人一個一個想起回家的理由。沒有一個理由是大的。狗老了，欠麵包店的錢，想看一眼湖。克蕾希妲在名冊上把三個村名描深，描到筆尖破紙。旁邊寫：找到了。她對部下說：邊民的損失，從今天起不準再寫成代價。"}],"relations":[{"id":"kora_ironmane","text":"把路標扛回來、在背面刻上「回程」的驛道巡守"},{"id":"tilda","text":"三個回家理由裡，「欠麵包店的錢」指的就是她的店"},{"id":"jorunn","text":"北方來的盾女。第十次雪崩沒有發生時，她的號角先到了山口"}]}},{"id":"kora_ironmane","story":{"quote":"路只有去程的時候，你就是回程。","background":"寇菈·鐵鬃在橡木鎮外的官道上巡守。她方向感好得近乎失禮，無法容忍有人在她守護的路上設伏，更無法容忍一塊指向「只有去、沒有回」的牌子。","ideal":"每一條路都要有兩個箭頭。","bond":"官道中央那塊路標。背面是她刻的「回程」兩個字。","flaw":"刻下去的字她不允許別人改，包括刻錯的時候。這次她沒有刻錯。","chapters":[{"title":"只有去程","text":"路標是一夜之間出現的，插在官道正中，字很新，指向一條她跑過上百次、卻忽然沒有回程的路。牲口先知道。羊不肯往北，飛獸不肯往北，馱獸在三里外停下。寇菈把路標拔起來，沒有劈了。她要看是誰還需要這塊木頭。"},{"title":"兩個箭頭","text":"北境的人走進懸停的雪，裡面一息、外面一天。南邊的鹽道全員平安，卻都記得一輛不存在的第七車。寇菈沒有跟著任何一隊走完。她留在官道上，把每一條出去的路都畫上回來的箭頭。有人笑她畫在泥裡，一場雨就沒了。她說：那我就再畫。"},{"title":"刻上去","text":"封印之夜路標自己倒了。她把它扛回鎮上，在背面用刀刻了「回程」，刻得很深，深到木屑扎進指甲。然後插回原處，箭頭朝向橡木鎮。第一個走回去的是一個只想起「想看一眼湖」的村人。寇菈沒有送他。她只指了指牌子。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村、最後把名字描深的遊騎隊長"},{"id":"durik_snowpath","text":"說今天山路不能走、還是帶人繞遠路的高山嚮導"},{"id":"sabriya_saltroute","text":"鹽道商隊的主人。第七輛車的車轍停在寇菈這塊路標前面"}]}},{"id":"haru_frostmap","story":{"quote":"邊民的損失，從來不是「可接受的代價」。","ideal":"折返不是恥辱","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。","flaw":"寧可折返也不肯把理由說完整。晴·霜圖把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門邊，晴攤開結霜的地圖沉靜地說，他量了三次，北面的山脊線和舊圖差了半里"},{"title":"三村","text":"他們在地圖上找不到三村，晴·霜圖換了個辦法：不找村，找路。路上有馬糞、有車轍、有小孩掉的手套。晴·霜圖沿著手套走到一座村子門口，門口的人說：你們終於來了。我們一直不知道怎麼回去。"},{"title":"回程","text":"路標重新插回官道中央，背面刻著「回程」。晴·霜圖經過的時候摸了一下那兩個字。回到橡木鎮·城門之後，晴·霜圖把雪原製圖師的路線圖重畫了一遍——這一次每條路都畫了兩個箭頭。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。晴·霜圖走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。晴·霜圖是第一批走回程的人"}]}},{"id":"durik_snowpath","story":{"quote":"雪會記得每一個走過的人。問題是人不記得雪。","ideal":"每條路都要有回程。杜里克·雪徑把這句話留在橡木鎮·城門。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。杜里克·雪徑把這句話留在橡木鎮·城門。","flaw":"對路標的執著會讓同行的人受凍。杜里克·雪徑把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門邊，杜里克把探路杖往地上一頓，直說今天山路不能走；若你非去，他會勉為其難帶你繞遠路"},{"title":"數「我們」","text":"南邊那一組，杜里克·雪徑每天晚上數人。十二、十二、十二、十一。杜里克·雪徑沒有慌，照高山嚮導的訓練先確認不是數錯，然後倒著走了半天，在水脈邊找到第十二個人——他坐在那裡，說不記得自己要去哪裡。杜里克·雪徑說：跟我走，我記得。"},{"title":"想起來","text":"三村的人一個一個想起來為什麼要回來。杜里克·雪徑記下他們說的理由：狗老了、欠錢、想看湖。沒有一個理由是大的。杜里克·雪徑想起自己的理由，也不大。於是杜里克·雪徑也回來了。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。杜里克·雪徑走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。杜里克·雪徑是第一批走回程的人"}]}},{"id":"revna_slowfrost","story":{"quote":"走得慢的人在最後。但最後那個人，一定會到。","ideal":"邊民的損失不是代價。芮芙娜·緩霜把這句話留在鎮外·荒野小徑。","bond":"一支把慢的人留在最後、而最後那個人一定會到的隊伍。芮芙娜·緩霜把這句話留在鎮外·荒野小徑。","flaw":"找到以前不肯回家。芮芙娜·緩霜把這句話留在鎮外·荒野小徑。","chapters":[{"title":"路上少了的","text":"荒野雪線旁，芮芙娜守著一片飄雪懸停的緩時區；她需要有人幫忙把一名走進去的孩子帶出來，而區內每過一息，外面就是一天"},{"title":"第七輛車","text":"芮芙娜·緩霜替商隊數車。六輛。所有人都說七輛。芮芙娜·緩霜照緩時凍原巡守的規矩重數一遍，六輛。然後芮芙娜·緩霜看見第七道車轍——很新，上面沒有雪。芮芙娜·緩霜跟著它走了半里，車轍在一塊路標前停住。"},{"title":"第十次","text":"山口第十次崩塌之前，號角響了。芮芙娜·緩霜在山腳下聽見，那是五年來不存在的音。雪停在半空一息，然後落回去。芮芙娜·緩霜把這件事寫進緩時凍原巡守的紀錄，寫得很短：「第十次，沒有崩。」"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。芮芙娜·緩霜走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。芮芙娜·緩霜是第一批走回程的人"}]}},{"id":"hravna_slidehorn","story":{"quote":"出發很容易。要記得為什麼回來，才難。","ideal":"走得慢的人留在最後，最後的人一定要到。赫拉芙娜·崩角把這句話留在鎮外·荒野小徑。","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。赫拉芙娜·崩角把這句話留在鎮外·荒野小徑。","flaw":"把「我記得路」說得像命令。赫拉芙娜·崩角把這句話留在鎮外·荒野小徑。","chapters":[{"title":"路上少了的","text":"山口封鎖線前，赫拉芙娜攔下你們：這條路每年只崩一次，今年卻連崩了九次，而且每次都精準埋掉同一支商隊的補給"},{"title":"懸停的雪","text":"緩時區外面，赫拉芙娜·崩角負責計時。裡面每過一息，外面是一天。赫拉芙娜·崩角等了九天，用雪崩預警守的方式替裡面的人留下記號：每天在雪線上插一根棍子。第九根插下去的時候，有人牽著一個孩子走出來，問：今天幾號。"},{"title":"兩個箭頭","text":"冬天，赫拉芙娜·崩角替新來的人指路。指完去程，赫拉芙娜·崩角總會多說一句回程怎麼走。沒有人問為什麼。赫拉芙娜·崩角也不解釋，只是覺得做雪崩預警守的人應該把路講完整。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。赫拉芙娜·崩角走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。赫拉芙娜·崩角是第一批走回程的人"}]}},{"id":"wenna_icefathom","story":{"quote":"路只有去程的時候，你就是回程。溫娜·冰淵把這句話留在鎮外·荒野小徑。","ideal":"折返不是恥辱。溫娜·冰淵把這句話留在鎮外·荒野小徑。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。溫娜·冰淵把這句話留在鎮外·荒野小徑。","flaw":"寧可折返也不肯把理由說完整。溫娜·冰淵把這句話留在鎮外·荒野小徑。","chapters":[{"title":"路上少了的","text":"冰河營地，溫娜的銅鈴在無風時全部響起；她說裂隙底下有人繫著和她同款的確保繩，而那條繩子已經失蹤四十年"},{"title":"三村","text":"他們在地圖上找不到三村，溫娜·冰淵換了個辦法：不找村，找路。路上有馬糞、有車轍、有小孩掉的手套。溫娜·冰淵沿著手套走到一座村子門口，門口的人說：你們終於來了。我們一直不知道怎麼回去。"},{"title":"回程","text":"路標重新插回官道中央，背面刻著「回程」。溫娜·冰淵經過的時候摸了一下那兩個字。回到鎮外·荒野小徑之後，溫娜·冰淵把冰河裂隙嚮導的路線圖重畫了一遍——這一次每條路都畫了兩個箭頭。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。溫娜·冰淵走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。溫娜·冰淵是第一批走回程的人"}]}},{"id":"ekaterin_snowtribute","story":{"quote":"我寧可折返。折返的人才有下一次。葉卡特琳·雪貢把這句話留在橡木鎮·城門。","ideal":"每條路都要有回程。葉卡特琳·雪貢把這句話留在橡木鎮·城門。","bond":"一支把慢的人留在最後、而最後那個人一定會到的隊伍。葉卡特琳·雪貢把這句話留在橡木鎮·城門。","flaw":"對路標的執著會讓同行的人受凍。葉卡特琳·雪貢把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門的貢品交接處，葉卡特琳發現三個村莊繳來的箱子重量完全相同；封蠟是同一天壓的，但那三村之間隔著十天雪路"},{"title":"數「我們」","text":"南邊那一組，葉卡特琳·雪貢每天晚上數人。十二、十二、十二、十一。葉卡特琳·雪貢沒有慌，照貢品護送官的訓練先確認不是數錯，然後倒著走了半天，在水脈邊找到第十二個人——她坐在那裡，說不記得自己要去哪裡。葉卡特琳·雪貢說：跟我走，我記得。"},{"title":"想起來","text":"三村的人一個一個想起來為什麼要回來。葉卡特琳·雪貢記下他們說的理由：狗老了、欠錢、想看湖。沒有一個理由是大的。葉卡特琳·雪貢想起自己的理由，也不大。於是葉卡特琳·雪貢也回來了。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。葉卡特琳·雪貢走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。葉卡特琳·雪貢是第一批走回程的人"}]}},{"id":"maris_thornford","story":{"quote":"邊民的損失，從來不是「可接受的代價」。瑪莉絲·棘渡把這句話留在橡木鎮·城門。","ideal":"邊民的損失不是代價。瑪莉絲·棘渡把這句話留在橡木鎮·城門。","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。瑪莉絲·棘渡把這句話留在橡木鎮·城門。","flaw":"找到以前不肯回家。瑪莉絲·棘渡把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"邊鎮城門外，瑪莉絲攤開一張被血浸透的巡邏圖，指出三座前哨一夜失去訊號；她需要可靠的人沿舊獵徑同行"},{"title":"第七輛車","text":"瑪莉絲·棘渡替商隊數車。六輛。所有人都說七輛。瑪莉絲·棘渡照邊境巡察官的規矩重數一遍，六輛。然後瑪莉絲·棘渡看見第七道車轍——很新，上面沒有雪。瑪莉絲·棘渡跟著它走了半里，車轍在一塊路標前停住。"},{"title":"第十次","text":"山口第十次崩塌之前，號角響了。瑪莉絲·棘渡在山腳下聽見，那是五年來不存在的音。雪停在半空一息，然後落回去。瑪莉絲·棘渡把這件事寫進邊境巡察官的紀錄，寫得很短：「第十次，沒有崩。」"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。瑪莉絲·棘渡走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。瑪莉絲·棘渡是第一批走回程的人"}]}},{"id":"torvenna_rampartvow","story":{"quote":"雪會記得每一個走過的人。問題是人不記得雪。托爾溫娜·壘誓把這句話留在橡木鎮·城門。","ideal":"走得慢的人留在最後，最後的人一定要到。托爾溫娜·壘誓把這句話留在橡木鎮·城門。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。托爾溫娜·壘誓把這句話留在橡木鎮·城門。","flaw":"把「我記得路」說得像命令。托爾溫娜·壘誓把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"邊境堡壘門樓下，托爾溫娜請你見證換防：接替的部隊帶著正確的印信與口令，卻沒有一個人記得自己是從哪裡出發的"},{"title":"懸停的雪","text":"緩時區外面，托爾溫娜·壘誓負責計時。裡面每過一息，外面是一天。托爾溫娜·壘誓等了九天，用邊境堡壘守備長的方式替裡面的人留下記號：每天在雪線上插一根棍子。第九根插下去的時候，有人牽著一個孩子走出來，問：今天幾號。"},{"title":"兩個箭頭","text":"冬天，托爾溫娜·壘誓替新來的人指路。指完去程，托爾溫娜·壘誓總會多說一句回程怎麼走。沒有人問為什麼。托爾溫娜·壘誓也不解釋，只是覺得做邊境堡壘守備長的人應該把路講完整。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。托爾溫娜·壘誓走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。托爾溫娜·壘誓是第一批走回程的人"}]}},{"id":"nyra_dustwhisker","story":{"quote":"走得慢的人在最後。但最後那個人，一定會到。奈菈·塵鬚把這句話留在鎮外·荒野小徑。","ideal":"折返不是恥辱。奈菈·塵鬚把這句話留在鎮外·荒野小徑。","bond":"一支把慢的人留在最後、而最後那個人一定會到的隊伍。奈菈·塵鬚把這句話留在鎮外·荒野小徑。","flaw":"寧可折返也不肯把理由說完整。奈菈·塵鬚把這句話留在鎮外·荒野小徑。","chapters":[{"title":"路上少了的","text":"赤地商道旁，奈菈從風裡接到一撮帶血的雪；最近的雪山相隔兩週路程，她懷疑荒野出現了折疊距離的獸徑"},{"title":"三村","text":"他們在地圖上找不到三村，奈菈·塵鬚換了個辦法：不找村，找路。路上有馬糞、有車轍、有小孩掉的手套。奈菈·塵鬚沿著手套走到一座村子門口，門口的人說：你們終於來了。我們一直不知道怎麼回去。"},{"title":"回程","text":"路標重新插回官道中央，背面刻著「回程」。奈菈·塵鬚經過的時候摸了一下那兩個字。回到鎮外·荒野小徑之後，奈菈·塵鬚把赤地斥候的路線圖重畫了一遍——這一次每條路都畫了兩個箭頭。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。奈菈·塵鬚走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。奈菈·塵鬚是第一批走回程的人"}]}},{"id":"oru_woolcloak","story":{"quote":"出發很容易。要記得為什麼回來，才難。歐魯·絨袍把這句話留在鎮外·荒野小徑。","ideal":"每條路都要有回程。歐魯·絨袍把這句話留在鎮外·荒野小徑。","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。歐魯·絨袍把這句話留在鎮外·荒野小徑。","flaw":"對路標的執著會讓同行的人受凍。歐魯·絨袍把這句話留在鎮外·荒野小徑。","chapters":[{"title":"路上少了的","text":"荒野小徑旁的牧地邊，歐魯緩慢地開口，說他的羊群不肯再往北走，而牠們從來沒有錯過"},{"title":"數「我們」","text":"南邊那一組，歐魯·絨袍每天晚上數人。十二、十二、十二、十一。歐魯·絨袍沒有慌，照山羊牧人的訓練先確認不是數錯，然後倒著走了半天，在水脈邊找到第十二個人——他坐在那裡，說不記得自己要去哪裡。歐魯·絨袍說：跟我走，我記得。"},{"title":"想起來","text":"三村的人一個一個想起來為什麼要回來。歐魯·絨袍記下他們說的理由：狗老了、欠錢、想看湖。沒有一個理由是大的。歐魯·絨袍想起自己的理由，也不大。於是歐魯·絨袍也回來了。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。歐魯·絨袍走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。歐魯·絨袍是第一批走回程的人"}]}},{"id":"astrid_griffonhand","story":{"quote":"路只有去程的時候，你就是回程。阿絲翠德·獅鷲手把這句話留在橡木鎮·驛馬廄。","ideal":"邊民的損失不是代價。阿絲翠德·獅鷲手把這句話留在橡木鎮·驛馬廄。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。阿絲翠德·獅鷲手把這句話留在橡木鎮·驛馬廄。","flaw":"找到以前不肯回家。阿絲翠德·獅鷲手把這句話留在橡木鎮·驛馬廄。","chapters":[{"title":"路上少了的","text":"驛馬廄旁的獸欄前，阿絲翠德抱著幼獅鷲說，鎮上所有的飛獸這幾天都不肯往北飛"},{"title":"第七輛車","text":"阿絲翠德·獅鷲手替商隊數車。六輛。所有人都說七輛。阿絲翠德·獅鷲手照獅鷲訓練師的規矩重數一遍，六輛。然後阿絲翠德·獅鷲手看見第七道車轍——很新，上面沒有雪。阿絲翠德·獅鷲手跟著它走了半里，車轍在一塊路標前停住。"},{"title":"第十次","text":"山口第十次崩塌之前，號角響了。阿絲翠德·獅鷲手在山腳下聽見，那是五年來不存在的音。雪停在半空一息，然後落回去。阿絲翠德·獅鷲手把這件事寫進獅鷲訓練師的紀錄，寫得很短：「第十次，沒有崩。」"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。阿絲翠德·獅鷲手走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。阿絲翠德·獅鷲手是第一批走回程的人"}]}},{"id":"nadira_amberroute","story":{"quote":"我寧可折返。折返的人才有下一次。娜迪菈·琥珀道把這句話留在橡木鎮·驛馬廄。","ideal":"走得慢的人留在最後，最後的人一定要到。娜迪菈·琥珀道把這句話留在橡木鎮·驛馬廄。","bond":"一支把慢的人留在最後、而最後那個人一定會到的隊伍。娜迪菈·琥珀道把這句話留在橡木鎮·驛馬廄。","flaw":"把「我記得路」說得像命令。娜迪菈·琥珀道把這句話留在橡木鎮·驛馬廄。","chapters":[{"title":"路上少了的","text":"驛馬廄裡，娜迪菈的馱獸拒絕再往北；她說前方三里的空氣有琥珀香卻沒有樹，那通常代表商隊在那裡被整支「收走」過"},{"title":"懸停的雪","text":"緩時區外面，娜迪菈·琥珀道負責計時。裡面每過一息，外面是一天。娜迪菈·琥珀道等了九天，用琥珀香道嚮導的方式替裡面的人留下記號：每天在雪線上插一根棍子。第九根插下去的時候，有人牽著一個孩子走出來，問：今天幾號。"},{"title":"兩個箭頭","text":"冬天，娜迪菈·琥珀道替新來的人指路。指完去程，娜迪菈·琥珀道總會多說一句回程怎麼走。沒有人問為什麼。娜迪菈·琥珀道也不解釋，只是覺得做琥珀香道嚮導的人應該把路講完整。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。娜迪菈·琥珀道走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。娜迪菈·琥珀道是第一批走回程的人"}]}},{"id":"okoya_longstride","story":{"quote":"邊民的損失，從來不是「可接受的代價」。奧柯雅·長步把這句話留在橡木鎮·驛馬廄。","ideal":"折返不是恥辱。奧柯雅·長步把這句話留在橡木鎮·驛馬廄。","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。奧柯雅·長步把這句話留在橡木鎮·驛馬廄。","flaw":"寧可折返也不肯把理由說完整。奧柯雅·長步把這句話留在橡木鎮·驛馬廄。","chapters":[{"title":"路上少了的","text":"驛站馬廄前，奧柯雅帶回一張只跑了半程就中斷的路線圖：前哨的所有斥候都在同一個里程碑處折返，卻沒有人記得自己為什麼回頭"},{"title":"三村","text":"他們在地圖上找不到三村，奧柯雅·長步換了個辦法：不找村，找路。路上有馬糞、有車轍、有小孩掉的手套。奧柯雅·長步沿著手套走到一座村子門口，門口的人說：你們終於來了。我們一直不知道怎麼回去。"},{"title":"回程","text":"路標重新插回官道中央，背面刻著「回程」。奧柯雅·長步經過的時候摸了一下那兩個字。回到橡木鎮·驛馬廄之後，奧柯雅·長步把商隊前哨斥候的路線圖重畫了一遍——這一次每條路都畫了兩個箭頭。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。奧柯雅·長步走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。奧柯雅·長步是第一批走回程的人"}]}},{"id":"sabriya_saltroute","story":{"quote":"雪會記得每一個走過的人。問題是人不記得雪。莎布莉雅·鹽道把這句話留在橡木鎮·城門。","ideal":"每條路都要有回程。莎布莉雅·鹽道把這句話留在橡木鎮·城門。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。莎布莉雅·鹽道把這句話留在橡木鎮·城門。","flaw":"對路標的執著會讓同行的人受凍。莎布莉雅·鹽道把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門外，莎布莉雅的鹽道商隊全員平安抵達，唯獨每個人都記得旅途中有第七輛車；如今車轍還在，車和車夫卻不在"},{"title":"數「我們」","text":"南邊那一組，莎布莉雅·鹽道每天晚上數人。十二、十二、十二、十一。莎布莉雅·鹽道沒有慌，照跨漠鹽道商隊主的訓練先確認不是數錯，然後倒著走了半天，在水脈邊找到第十二個人——她坐在那裡，說不記得自己要去哪裡。莎布莉雅·鹽道說：跟我走，我記得。"},{"title":"想起來","text":"三村的人一個一個想起來為什麼要回來。莎布莉雅·鹽道記下他們說的理由：狗老了、欠錢、想看湖。沒有一個理由是大的。莎布莉雅·鹽道想起自己的理由，也不大。於是莎布莉雅·鹽道也回來了。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。莎布莉雅·鹽道走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。莎布莉雅·鹽道是第一批走回程的人"}]}},{"id":"sahra_duneward","story":{"quote":"走得慢的人在最後。但最後那個人，一定會到。莎菈·沙壘把這句話留在橡木鎮·城門。","ideal":"邊民的損失不是代價。莎菈·沙壘把這句話留在橡木鎮·城門。","bond":"一支把慢的人留在最後、而最後那個人一定會到的隊伍。莎菈·沙壘把這句話留在橡木鎮·城門。","flaw":"找到以前不肯回家。莎菈·沙壘把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門工事旁，莎菈的沙粒模型自行裂開一道向北延伸的縫；她說地下某個巨大空洞正在靠近城牆"},{"title":"第七輛車","text":"莎菈·沙壘替商隊數車。六輛。所有人都說七輛。莎菈·沙壘照流沙建築師的規矩重數一遍，六輛。然後莎菈·沙壘看見第七道車轍——很新，上面沒有雪。莎菈·沙壘跟著它走了半里，車轍在一塊路標前停住。"},{"title":"第十次","text":"山口第十次崩塌之前，號角響了。莎菈·沙壘在山腳下聽見，那是五年來不存在的音。雪停在半空一息，然後落回去。莎菈·沙壘把這件事寫進流沙建築師的紀錄，寫得很短：「第十次，沒有崩。」"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。莎菈·沙壘走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。莎菈·沙壘是第一批走回程的人"}]}},{"id":"ebriel_springdowse","story":{"quote":"出發很容易。要記得為什麼回來，才難。艾布莉爾·湧探把這句話留在橡木鎮·市集廣場。","ideal":"走得慢的人留在最後，最後的人一定要到。艾布莉爾·湧探把這句話留在橡木鎮·市集廣場。","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。艾布莉爾·湧探把這句話留在橡木鎮·市集廣場。","flaw":"把「我記得路」說得像命令。艾布莉爾·湧探把這句話留在橡木鎮·市集廣場。","chapters":[{"title":"路上少了的","text":"鎮中心水井旁，艾布莉爾證實全鎮的水脈在一夜之間被整條抽走；她能追蹤那條水脈，但終點在沙漠深處的敵對邊塞下方"},{"title":"懸停的雪","text":"緩時區外面，艾布莉爾·湧探負責計時。裡面每過一息，外面是一天。艾布莉爾·湧探等了九天，用荒漠遠征水脈探測師的方式替裡面的人留下記號：每天在雪線上插一根棍子。第九根插下去的時候，有人牽著一個孩子走出來，問：今天幾號。"},{"title":"兩個箭頭","text":"冬天，艾布莉爾·湧探替新來的人指路。指完去程，艾布莉爾·湧探總會多說一句回程怎麼走。沒有人問為什麼。艾布莉爾·湧探也不解釋，只是覺得做荒漠遠征水脈探測師的人應該把路講完整。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。艾布莉爾·湧探走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。艾布莉爾·湧探是第一批走回程的人"}]}},{"id":"ghoran_redmesa","story":{"quote":"路只有去程的時候，你就是回程。戈蘭·赤臺把這句話留在橡木鎮·城門。","ideal":"折返不是恥辱。戈蘭·赤臺把這句話留在橡木鎮·城門。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。戈蘭·赤臺把這句話留在橡木鎮·城門。","flaw":"寧可折返也不肯把理由說完整。戈蘭·赤臺把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門外，戈蘭帶回一支無人商隊，貨物與營火都完好，所有護衛卻同時消失；車轍顯示他們仍在繼續趕路"},{"title":"三村","text":"他們在地圖上找不到三村，戈蘭·赤臺換了個辦法：不找村，找路。路上有馬糞、有車轍、有小孩掉的手套。戈蘭·赤臺沿著手套走到一座村子門口，門口的人說：你們終於來了。我們一直不知道怎麼回去。"},{"title":"回程","text":"路標重新插回官道中央，背面刻著「回程」。戈蘭·赤臺經過的時候摸了一下那兩個字。回到橡木鎮·城門之後，戈蘭·赤臺把高原商隊前騎的路線圖重畫了一遍——這一次每條路都畫了兩個箭頭。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。戈蘭·赤臺走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。戈蘭·赤臺是第一批走回程的人"}]}},{"id":"krix","story":{"quote":"我寧可折返。折返的人才有下一次。克里克斯·蟲鳴把這句話留在橡木鎮·城門。","ideal":"每條路都要有回程。克里克斯·蟲鳴把這句話留在橡木鎮·城門。","bond":"一支把慢的人留在最後、而最後那個人一定會到的隊伍。克里克斯·蟲鳴把這句話留在橡木鎮·城門。","flaw":"對路標的執著會讓同行的人受凍。克里克斯·蟲鳴把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門外的沙塵中，克里克斯四臂持械無聲逼近，複眼閃動，以「我們」自稱冷冷確認你不是它要獵的逃犯"},{"title":"數「我們」","text":"南邊那一組，克里克斯·蟲鳴每天晚上數人。十二、十二、十二、十一。克里克斯·蟲鳴沒有慌，照沙漠賞金獵人的訓練先確認不是數錯，然後倒著走了半天，在水脈邊找到第十二個人——克里克斯·蟲鳴坐在那裡，說不記得自己要去哪裡。克里克斯·蟲鳴說：跟我走，我記得。"},{"title":"想起來","text":"三村的人一個一個想起來為什麼要回來。克里克斯·蟲鳴記下他們說的理由：狗老了、欠錢、想看湖。沒有一個理由是大的。克里克斯·蟲鳴想起自己的理由，也不大。於是克里克斯·蟲鳴也回來了。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。克里克斯·蟲鳴走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。克里克斯·蟲鳴是第一批走回程的人"}]}},{"id":"fionnula_wingfurrow","story":{"quote":"邊民的損失，從來不是「可接受的代價」。菲昂努菈·翼壟把這句話留在橡木鎮·攤販街。","ideal":"邊民的損失不是代價。菲昂努菈·翼壟把這句話留在橡木鎮·攤販街。","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。菲昂努菈·翼壟把這句話留在橡木鎮·攤販街。","flaw":"找到以前不肯回家。菲昂努菈·翼壟把這句話留在橡木鎮·攤販街。","chapters":[{"title":"路上少了的","text":"市集鳥販攤前，菲昂努菈認出籠中的鳥全屬於同一支從未在此過境的遷徙群；牠們身上的環標，寫著北方一座無人邊塞的名字"},{"title":"第七輛車","text":"菲昂努菈·翼壟替商隊數車。六輛。所有人都說七輛。菲昂努菈·翼壟照候鳥遷徙牧者的規矩重數一遍，六輛。然後菲昂努菈·翼壟看見第七道車轍——很新，上面沒有雪。菲昂努菈·翼壟跟著它走了半里，車轍在一塊路標前停住。"},{"title":"第十次","text":"山口第十次崩塌之前，號角響了。菲昂努菈·翼壟在山腳下聽見，那是五年來不存在的音。雪停在半空一息，然後落回去。菲昂努菈·翼壟把這件事寫進候鳥遷徙牧者的紀錄，寫得很短：「第十次，沒有崩。」"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。菲昂努菈·翼壟走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。菲昂努菈·翼壟是第一批走回程的人"}]}},{"id":"zephrine_highsignal","story":{"quote":"雪會記得每一個走過的人。問題是人不記得雪。澤芙琳·高號把這句話留在橡木鎮·瞭望塔。","ideal":"走得慢的人留在最後，最後的人一定要到。澤芙琳·高號把這句話留在橡木鎮·瞭望塔。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。澤芙琳·高號把這句話留在橡木鎮·瞭望塔。","flaw":"把「我記得路」說得像命令。澤芙琳·高號把這句話留在橡木鎮·瞭望塔。","chapters":[{"title":"路上少了的","text":"信號塔頂，澤芙琳指著遠方三座烽燧：它們同時打出「安全」，但其中一座在昨夜就已經被燒毀了"},{"title":"懸停的雪","text":"緩時區外面，澤芙琳·高號負責計時。裡面每過一息，外面是一天。澤芙琳·高號等了九天，用空域信號官的方式替裡面的人留下記號：每天在雪線上插一根棍子。第九根插下去的時候，有人牽著一個孩子走出來，問：今天幾號。"},{"title":"兩個箭頭","text":"冬天，澤芙琳·高號替新來的人指路。指完去程，澤芙琳·高號總會多說一句回程怎麼走。沒有人問為什麼。澤芙琳·高號也不解釋，只是覺得做空域信號官的人應該把路講完整。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。澤芙琳·高號走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。澤芙琳·高號是第一批走回程的人"}]}},{"id":"maeve_roadsteel","story":{"quote":"走得慢的人在最後。但最後那個人，一定會到。梅芙·旅鋼把這句話留在橡木鎮·城門。","ideal":"折返不是恥辱。梅芙·旅鋼把這句話留在橡木鎮·城門。","bond":"一支把慢的人留在最後、而最後那個人一定會到的隊伍。梅芙·旅鋼把這句話留在橡木鎮·城門。","flaw":"寧可折返也不肯把理由說完整。梅芙·旅鋼把這句話留在橡木鎮·城門。","chapters":[{"title":"路上少了的","text":"城門邊的馬樁旁，梅芙一手按著舊盾坦率地說她接了一趟護送，路上少了一個人，她要找回來"},{"title":"三村","text":"他們在地圖上找不到三村，梅芙·旅鋼換了個辦法：不找村，找路。路上有馬糞、有車轍、有小孩掉的手套。梅芙·旅鋼沿著手套走到一座村子門口，門口的人說：你們終於來了。我們一直不知道怎麼回去。"},{"title":"回程","text":"路標重新插回官道中央，背面刻著「回程」。梅芙·旅鋼經過的時候摸了一下那兩個字。回到橡木鎮·城門之後，梅芙·旅鋼把遊俠騎士的路線圖重畫了一遍——這一次每條路都畫了兩個箭頭。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。梅芙·旅鋼走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。梅芙·旅鋼是第一批走回程的人"}]}},{"id":"ithra_trackthorn","story":{"quote":"出發很容易。要記得為什麼回來，才難。伊絲菈·蹤棘把這句話留在鎮外·荒野小徑。","ideal":"每條路都要有回程。伊絲菈·蹤棘把這句話留在鎮外·荒野小徑。","bond":"三村名冊上被描深的三個名字，旁邊寫：找到了。伊絲菈·蹤棘把這句話留在鎮外·荒野小徑。","flaw":"對路標的執著會讓同行的人受凍。伊絲菈·蹤棘把這句話留在鎮外·荒野小徑。","chapters":[{"title":"路上少了的","text":"荒原營火旁，伊絲菈攤開她的足跡拓本：同一頭巨獸的蹄印每隔三十里出現一次，中間沒有任何過渡，像是牠一步跨過了整片平原"},{"title":"數「我們」","text":"南邊那一組，伊絲菈·蹤棘每天晚上數人。十二、十二、十二、十一。伊絲菈·蹤棘沒有慌，照巨獸遷徙追蹤者的訓練先確認不是數錯，然後倒著走了半天，在水脈邊找到第十二個人——她坐在那裡，說不記得自己要去哪裡。伊絲菈·蹤棘說：跟我走，我記得。"},{"title":"想起來","text":"三村的人一個一個想起來為什麼要回來。伊絲菈·蹤棘記下他們說的理由：狗老了、欠錢、想看湖。沒有一個理由是大的。伊絲菈·蹤棘想起自己的理由，也不大。於是伊絲菈·蹤棘也回來了。"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。伊絲菈·蹤棘走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。伊絲菈·蹤棘是第一批走回程的人"}]}},{"id":"asterion_sunroad","story":{"quote":"路只有去程的時候，你就是回程。阿斯特里昂·陽徑把這句話留在鎮外·荒野小徑。","ideal":"邊民的損失不是代價。阿斯特里昂·陽徑把這句話留在鎮外·荒野小徑。","bond":"官道中央那塊路標。背面後來刻了「回程」兩個字。阿斯特里昂·陽徑把這句話留在鎮外·荒野小徑。","flaw":"找到以前不肯回家。阿斯特里昂·陽徑把這句話留在鎮外·荒野小徑。","chapters":[{"title":"路上少了的","text":"荒野岔路上，阿斯特里昂指出第三條路只有在講完一個真實故事後才會出現；那是前往失蹤村落最快也最安全的方向"},{"title":"第七輛車","text":"阿斯特里昂·陽徑替商隊數車。六輛。所有人都說七輛。阿斯特里昂·陽徑照妖精岔路嚮導的規矩重數一遍，六輛。然後阿斯特里昂·陽徑看見第七道車轍——很新，上面沒有雪。阿斯特里昂·陽徑跟著它走了半里，車轍在一塊路標前停住。"},{"title":"第十次","text":"山口第十次崩塌之前，號角響了。阿斯特里昂·陽徑在山腳下聽見，那是五年來不存在的音。雪停在半空一息，然後落回去。阿斯特里昂·陽徑把這件事寫進妖精岔路嚮導的紀錄，寫得很短：「第十次，沒有崩。」"}],"relations":[{"id":"cressida_marchwarden","text":"兩年找不到三村的遊騎隊長。阿斯特里昂·陽徑走的那條路，是她名冊上的一行"},{"id":"kora_ironmane","text":"把路標扛回來、刻上「回程」的驛道巡守。阿斯特里昂·陽徑是第一批走回程的人"}]}},{"id":"bellamira_brinehalt","story":{"quote":"繩結會說話。死者打的結，和活人打的不一樣。","background":"貝拉米菈·止潮在鹽港帶船。她用歌聲統一全船的節奏，也用節奏決定哪一趟航程不該出。高價不是理由。船上的繩如果是死者打的，她會把合約退回去。","ideal":"活著的人才配被帶去海上。死者也配被送回該在的地方。","bond":"三年前她沒有拦住的那支船隊，和後來慢一拍的那十二個節奏。","flaw":"拒絕得太快，有時讓委託人連解釋的機會都沒有。","chapters":[{"title":"死者的結","text":"那趟航程出價高得失禮。貝拉米菈還是上了委託船，看了一眼纜繩，就下來了。結是對的，對得太對。那是只有溺過的人才會打的結，打結的人已經不需要再被水手的口訣記住。她把合約撕了。不是發脾氣。是不載。"},{"title":"逆流","text":"珊瑚全部朝黯河上游倒。船隊沒有沉在海裡。它被什麼東西逆著河拉進了湖底。哈瓦說三年前那支船隊是他送出港的，然後沉默。貝拉米菈問了那天的風。風不對。那天不該出港。她沒有罵哈瓦。她把不該出港這四個字記在自己的潮汐簿上，記在自己名下。"},{"title":"慢一拍","text":"封印之夜之後，十一具遺體順著黯河漂回鹽港，每具都繫著一個活人才打得出的結。像有人在下面學會了，想把他們交還。貝拉米菈接了送行的那一趟。船上十二個人，她喊的節奏比平常慢一拍。慢的那一拍沒有人划。那一拍是給十一個名字的。第十二個拍子落下的時候，她自己的手在抖。她沒有停。"}],"relations":[{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者"},{"id":"halvar","text":"三年前把船隊送出港的船長。風不對的那一天，他們兩個都在碼頭"},{"id":"garrick","text":"湖上的渡船夫。他說門關了的同一刻，鹽港的水把人還了回來"}]}},{"id":"nualith_hullshadow","story":{"quote":"還有遺體沒有安置，就不叫打撈。叫打擾。","background":"努雅莉絲·舟影潛進沉船。她下水前一定先聽同伴的氣息，拒絕打開還有人沒被安放的艙室。對她來說，名冊不是紙。名冊是她在黑暗裡數到的數字，數字不能少，也不能多得沒有名字。","ideal":"每一具都要有名字，才算被接回家。","bond":"比乘客名冊多出來的十一具。她拒絕把他們叫做「誤差」。","flaw":"數字一旦對不上，她會停止所有人的工作，包括已經付了錢的人。","chapters":[{"title":"多十一","text":"船艙裡她數到第二十具的時候，手上的名冊只有九個名字。她又數了一遍。還是多十一。努雅莉絲浮出水面，把後續作業停了。甲板上有人罵她耽誤工期。她說：你們在工期。我在人家的身體裡面。沒有安置以前，誰都不許再下去。"},{"title":"黑湖的石頭","text":"她替每一具寫特徵。左手缺指。頸上的鹽。懷裡一塊不屬於海的石頭，是黑湖的。寫到第五具她不得不上岸坐著，因為手會把字寫歪。歪了就重寫。同行的人問她要不要換人寫。她說不要。這是她數到的。就要她寫完。"},{"title":"對上了","text":"十一具順著黯河回來的那天，名冊終於對上。努雅莉絲在碼頭上認其中一具，用的是只有潛過那艘船的人才知道的細節：第三根肋骨上有一道舊傷，不是溺水留下的。認完她走到水邊，對海說了一句謝謝。說得很輕。然後她去寫安置的名字。一個都沒有留空。"}],"relations":[{"id":"bellamira_brinehalt","text":"後來用慢一拍的節奏把十一個名字送回去的帆索長"},{"id":"saoirse_coralvow","text":"帶他們看珊瑚倒向黯河上游的礁醫"},{"id":"maren","text":"黑湖的水文學者。懷裡那塊石頭的來源是她認的"}]}},{"id":"aelor_saltsail","story":{"quote":"繩結會說話。死者打的結，和活人打的不一樣。","ideal":"還回來的名字要一個一個寫","bond":"一個活人才打得出的結。","flaw":"數字對不上就讓所有人停工。艾洛爾·鹽帆把這句話留在橡木鎮·攤販街。","chapters":[{"title":"水說的話","text":"港市帆鋪內，艾洛爾展示一幅從沉船取回的完整舊帆；每到午夜，它便鼓起並把整間店拖向內陸方向"},{"title":"禁區礁盤","text":"莎綺絲帶他們潛進禁區，艾洛爾·鹽帆負責在水面計時。珊瑚全朝一個方向倒，艾洛爾·鹽帆在船上拿符風帆匠的工具對了一下方位：黯河上游。艾洛爾·鹽帆把這個方位寫在手背上，怕自己上岸以後不信。"},{"title":"對上了","text":"十一具遺體順著黯河漂回鹽港，名冊終於對上。艾洛爾·鹽帆在碼頭上，替其中一具認了身分——用符風帆匠才知道的細節。認完，艾洛爾·鹽帆走到水邊，第一次對海說了一句話。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。艾洛爾·鹽帆在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。艾洛爾·鹽帆替她記下其中幾具的特徵"}]}},{"id":"koru_wreckwhisper","story":{"quote":"我信海流，不信羅盤。羅盤是人做的。","ideal":"遺體安置完才叫打撈。寇魯·沉船語把這句話留在鎮外·湖畔。","bond":"三年前從鹽港出發、再沒有回來的那支船隊。寇魯·沉船語把這句話留在鎮外·湖畔。","flaw":"拒絕得太快。寇魯·沉船語把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"港口殘骸堆旁，寇魯用三艘不同沉船的碎響拼出完整座標；位置在乾燥內陸，卻伴隨巨浪撞擊船身的聲音"},{"title":"哈瓦的義肢","text":"哈瓦說三年前的船隊是他送出港的，寇魯·沉船語當時在場——寇魯·沉船語記得那天的風向。寇魯·沉船語把風向告訴哈瓦，哈瓦沉默很久，說：那風不對。那天不該出港。"},{"title":"慢一拍","text":"貝拉米菈的船出港時喊的節奏慢一拍。寇魯·沉船語在船上，跟著那個節奏做自己的事。慢的那一拍沒有人划，寇魯·沉船語知道那是給誰留的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。寇魯·沉船語在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。寇魯·沉船語替她記下其中幾具的特徵"}]}},{"id":"lyris_reefblade","story":{"quote":"船隊沒有回來。但海把名字一個一個還了。","ideal":"海不騙人，海圖會。莉芮絲·礁刃把這句話留在鎮外·湖畔。","bond":"黯河。它把湖裡的事帶到海，也把海裡的事帶回湖。莉芮絲·礁刃把這句話留在鎮外·湖畔。","flaw":"對三年前的風向耿耿於懷。莉芮絲·礁刃把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖畔碼頭，莉芮絲拖回一扇刻有古地城徽記的石門；門明明沉在湖底，縫裡卻不斷吹出乾燥冷風"},{"title":"名冊","text":"努雅莉絲說遺體比名冊多十一具，莉芮絲·礁刃第一個信。做沉船打撈者的人數東西從不數錯。莉芮絲·礁刃替她把十一具的特徵一一記下：左手缺指、頸上有鹽痂、懷裡抱著一塊黑湖的石頭。"},{"title":"見證","text":"水下的使節團要一位陸上的中立見證人。莉芮絲·礁刃去了，用沉船打撈者的身分。見證的內容只有兩行：海還回來的，和海留下的。莉芮絲·礁刃簽了名，覺得這兩行比一輩子的工作都重。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。莉芮絲·礁刃在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。莉芮絲·礁刃替她記下其中幾具的特徵"}]}},{"id":"syrentha_coralpike","story":{"quote":"燈塔不是給看得見的人點的。","ideal":"活人才配被帶出海。希倫莎·珊矛把這句話留在鎮外·湖畔。","bond":"一個活人才打得出的結。希倫莎·珊矛把這句話留在鎮外·湖畔。","flaw":"在碼頭上說謝謝說得太輕，輕到別人以為沒事。希倫莎·珊矛把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"海港防波堤上，希倫莎展示一片帶有鎖鏈磨痕的巨鱗；某人正把深海巨獸驅向商船航線，她需要潛伴找出原因"},{"title":"逆流","text":"他們沿著黯河逆流而上，希倫莎·珊矛在船上。每過一道河灣，希倫莎·珊矛用深潮魚叉手的辦法量一次水——愈往上愈冷，愈冷愈像海。到了湖口，希倫莎·珊矛說：這不是河水。這是三年前的海水，一直沒有走。"},{"title":"照到對岸","text":"燈塔的光重新照到對岸那一夜，希倫莎·珊矛在鎮外·湖畔。希倫莎·珊矛沒有歡呼，只是把深潮魚叉手的東西收好，然後想起三年前那天的風向。這一次風是對的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。希倫莎·珊矛在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。希倫莎·珊矛替她記下其中幾具的特徵"}]}},{"id":"helga_deepcurrent","story":{"quote":"海不會騙人。騙人的是海圖。海爾嘉·深流把這句話留在鎮外·湖畔。","ideal":"還回來的名字要一個一個寫。海爾嘉·深流把這句話留在鎮外·湖畔。","bond":"三年前從鹽港出發、再沒有回來的那支船隊。海爾嘉·深流把這句話留在鎮外·湖畔。","flaw":"數字對不上就讓所有人停工。海爾嘉·深流把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"寒港外，海爾嘉發現所有巨獸在同一天偏離千年航線；牠們不是追逐食物，而是在為某個從海溝升起的東西讓路"},{"title":"禁區礁盤","text":"莎綺絲帶他們潛進禁區，海爾嘉·深流負責在水面計時。珊瑚全朝一個方向倒，海爾嘉·深流在船上拿寒海巨獸監測員的工具對了一下方位：黯河上游。海爾嘉·深流把這個方位寫在手背上，怕自己上岸以後不信。"},{"title":"對上了","text":"十一具遺體順著黯河漂回鹽港，名冊終於對上。海爾嘉·深流在碼頭上，替其中一具認了身分——用寒海巨獸監測員才知道的細節。認完，海爾嘉·深流走到水邊，第一次對海說了一句話。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。海爾嘉·深流在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。海爾嘉·深流替她記下其中幾具的特徵"}]}},{"id":"halvenne_leadline","story":{"quote":"還有遺體沒有安置，就不叫打撈，叫打擾。哈爾溫·測繩把這句話留在鎮外·湖畔。","ideal":"遺體安置完才叫打撈。哈爾溫·測繩把這句話留在鎮外·湖畔。","bond":"黯河。它把湖裡的事帶到海，也把海裡的事帶回湖。哈爾溫·測繩把這句話留在鎮外·湖畔。","flaw":"拒絕得太快。哈爾溫·測繩把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"海灣測量船上，哈爾溫請你核對她的水深紀錄：同一片淺灘白天只有兩尋，入夜後卻深不見底，而漁民正被人勸著在夜裡出海"},{"title":"哈瓦的義肢","text":"哈瓦說三年前的船隊是他送出港的，哈爾溫·測繩當時在場——哈爾溫·測繩記得那天的風向。哈爾溫·測繩把風向告訴哈瓦，哈瓦沉默很久，說：那風不對。那天不該出港。"},{"title":"慢一拍","text":"貝拉米菈的船出港時喊的節奏慢一拍。哈爾溫·測繩在船上，跟著那個節奏做自己的事。慢的那一拍沒有人划，哈爾溫·測繩知道那是給誰留的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。哈爾溫·測繩在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。哈爾溫·測繩替她記下其中幾具的特徵"}]}},{"id":"varkesh_beaconcrest","story":{"quote":"繩結會說話。死者打的結，和活人打的不一樣。瓦凱什·烽冠把這句話留在橡木鎮·瞭望塔。","ideal":"海不騙人，海圖會。瓦凱什·烽冠把這句話留在橡木鎮·瞭望塔。","bond":"一個活人才打得出的結。瓦凱什·烽冠把這句話留在橡木鎮·瞭望塔。","flaw":"對三年前的風向耿耿於懷。瓦凱什·烽冠把這句話留在橡木鎮·瞭望塔。","chapters":[{"title":"水說的話","text":"海岬燈塔上，瓦凱什連續三夜收到來自陸地方向的海難燈號；訊號使用一艘沉沒五十年的船才知道的密碼"},{"title":"名冊","text":"努雅莉絲說遺體比名冊多十一具，瓦凱什·烽冠第一個信。做孤岬燈塔守的人數東西從不數錯。瓦凱什·烽冠替她把十一具的特徵一一記下：左手缺指、頸上有鹽痂、懷裡抱著一塊黑湖的石頭。"},{"title":"見證","text":"水下的使節團要一位陸上的中立見證人。瓦凱什·烽冠去了，用孤岬燈塔守的身分。見證的內容只有兩行：海還回來的，和海留下的。瓦凱什·烽冠簽了名，覺得這兩行比一輩子的工作都重。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。瓦凱什·烽冠在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。瓦凱什·烽冠替她記下其中幾具的特徵"}]}},{"id":"neris_wavecompass","story":{"quote":"我信海流，不信羅盤。羅盤是人做的。奈里斯·浪針把這句話留在鎮外·湖畔。","ideal":"活人才配被帶出海。奈里斯·浪針把這句話留在鎮外·湖畔。","bond":"三年前從鹽港出發、再沒有回來的那支船隊。奈里斯·浪針把這句話留在鎮外·湖畔。","flaw":"在碼頭上說謝謝說得太輕，輕到別人以為沒事。奈里斯·浪針把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"碼頭盡頭，奈里斯攤開一張自行滲水的海圖，新增的洋流穿過陸地直達一處廢棄礦坑；他想找人驗證那條不可能的航道"},{"title":"逆流","text":"他們沿著黯河逆流而上，奈里斯·浪針在船上。每過一道河灣，奈里斯·浪針用遠洋領航員的辦法量一次水——愈往上愈冷，愈冷愈像海。到了湖口，奈里斯·浪針說：這不是河水。這是三年前的海水，一直沒有走。"},{"title":"照到對岸","text":"燈塔的光重新照到對岸那一夜，奈里斯·浪針在鎮外·湖畔。奈里斯·浪針沒有歡呼，只是把遠洋領航員的東西收好，然後想起三年前那天的風向。這一次風是對的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。奈里斯·浪針在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。奈里斯·浪針替她記下其中幾具的特徵"}]}},{"id":"sinaia_sextantveil","story":{"quote":"船隊沒有回來。但海把名字一個一個還了。席奈雅·星規把這句話留在橡木鎮·公會藏書閣。","ideal":"還回來的名字要一個一個寫。席奈雅·星規把這句話留在橡木鎮·公會藏書閣。","bond":"黯河。它把湖裡的事帶到海，也把海裡的事帶回湖。席奈雅·星規把這句話留在橡木鎮·公會藏書閣。","flaw":"數字對不上就讓所有人停工。席奈雅·星規把這句話留在橡木鎮·公會藏書閣。","chapters":[{"title":"水說的話","text":"公會藏書閣裡，席奈雅攤開一份委託星圖：圖上多出一顆她從未見過的導航星，而所有依它航行的船，都準時抵達了不存在的港口"},{"title":"禁區礁盤","text":"莎綺絲帶他們潛進禁區，席奈雅·星規負責在水面計時。珊瑚全朝一個方向倒，席奈雅·星規在船上拿遠洋天文導航師的工具對了一下方位：黯河上游。席奈雅·星規把這個方位寫在手背上，怕自己上岸以後不信。"},{"title":"對上了","text":"十一具遺體順著黯河漂回鹽港，名冊終於對上。席奈雅·星規在碼頭上，替其中一具認了身分——用遠洋天文導航師才知道的細節。認完，席奈雅·星規走到水邊，第一次對海說了一句話。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。席奈雅·星規在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。席奈雅·星規替她記下其中幾具的特徵"}]}},{"id":"saoirse_coralvow","story":{"quote":"燈塔不是給看得見的人點的。莎綺絲·珊誓把這句話留在鎮外·湖畔。","ideal":"遺體安置完才叫打撈。莎綺絲·珊誓把這句話留在鎮外·湖畔。","bond":"一個活人才打得出的結。莎綺絲·珊誓把這句話留在鎮外·湖畔。","flaw":"拒絕得太快。莎綺絲·珊誓把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"海灣岸邊，莎綺絲請你護送她潛入禁區礁盤；那裡的珊瑚全部朝同一個方向倒伏，而倒伏的日期正是三年前船隊失蹤的那天"},{"title":"哈瓦的義肢","text":"哈瓦說三年前的船隊是他送出港的，莎綺絲·珊誓當時在場——莎綺絲·珊誓記得那天的風向。莎綺絲·珊誓把風向告訴哈瓦，哈瓦沉默很久，說：那風不對。那天不該出港。"},{"title":"慢一拍","text":"貝拉米菈的船出港時喊的節奏慢一拍。莎綺絲·珊誓在船上，跟著那個節奏做自己的事。慢的那一拍沒有人划，莎綺絲·珊誓知道那是給誰留的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。莎綺絲·珊誓在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。莎綺絲·珊誓替她記下其中幾具的特徵"}]}},{"id":"quenaria_tidepavilion","story":{"quote":"海不會騙人。騙人的是海圖。昆娜莉雅·潮亭把這句話留在鎮外·湖畔。","ideal":"海不騙人，海圖會。昆娜莉雅·潮亭把這句話留在鎮外·湖畔。","bond":"三年前從鹽港出發、再沒有回來的那支船隊。昆娜莉雅·潮亭把這句話留在鎮外·湖畔。","flaw":"對三年前的風向耿耿於懷。昆娜莉雅·潮亭把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖畔接待亭前，昆娜莉雅擺出七套問候牌都無人回應；水面下的使節團一直在等，卻堅持要一位「陸上的中立見證人」先入水"},{"title":"名冊","text":"努雅莉絲說遺體比名冊多十一具，昆娜莉雅·潮亭第一個信。做海外使節接待亭主的人數東西從不數錯。昆娜莉雅·潮亭替她把十一具的特徵一一記下：左手缺指、頸上有鹽痂、懷裡抱著一塊黑湖的石頭。"},{"title":"見證","text":"水下的使節團要一位陸上的中立見證人。昆娜莉雅·潮亭去了，用海外使節接待亭主的身分。見證的內容只有兩行：海還回來的，和海留下的。昆娜莉雅·潮亭簽了名，覺得這兩行比一輩子的工作都重。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。昆娜莉雅·潮亭在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。昆娜莉雅·潮亭替她記下其中幾具的特徵"}]}},{"id":"tamsyn_wavecairn","story":{"quote":"還有遺體沒有安置，就不叫打撈，叫打擾。塔姆欣·浪塚把這句話留在鎮外·湖畔。","ideal":"活人才配被帶出海。塔姆欣·浪塚把這句話留在鎮外·湖畔。","bond":"黯河。它把湖裡的事帶到海，也把海裡的事帶回湖。塔姆欣·浪塚把這句話留在鎮外·湖畔。","flaw":"在碼頭上說謝謝說得太輕，輕到別人以為沒事。塔姆欣·浪塚把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖濱碼頭，塔姆欣需要幫手重立被拔走的三座石標；每晚拔標的東西留下的痕跡，比整艘漁船還寬"},{"title":"逆流","text":"他們沿著黯河逆流而上，塔姆欣·浪塚在船上。每過一道河灣，塔姆欣·浪塚用深海航道立標員的辦法量一次水——愈往上愈冷，愈冷愈像海。到了湖口，塔姆欣·浪塚說：這不是河水。這是三年前的海水，一直沒有走。"},{"title":"照到對岸","text":"燈塔的光重新照到對岸那一夜，塔姆欣·浪塚在鎮外·湖畔。塔姆欣·浪塚沒有歡呼，只是把深海航道立標員的東西收好，然後想起三年前那天的風向。這一次風是對的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。塔姆欣·浪塚在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。塔姆欣·浪塚替她記下其中幾具的特徵"}]}},{"id":"pelagia_deepcurrent","story":{"quote":"繩結會說話。死者打的結，和活人打的不一樣。佩菈姬雅·深流把這句話留在鎮外·湖畔。","ideal":"還回來的名字要一個一個寫。佩菈姬雅·深流把這句話留在鎮外·湖畔。","bond":"一個活人才打得出的結。佩菈姬雅·深流把這句話留在鎮外·湖畔。","flaw":"數字對不上就讓所有人停工。佩菈姬雅·深流把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖畔水面豎起一道流動拱門，佩菈姬雅守在門前請求援手；另一側本該是水元素界，如今卻吹出沙漠熱風"},{"title":"禁區礁盤","text":"莎綺絲帶他們潛進禁區，佩菈姬雅·深流負責在水面計時。珊瑚全朝一個方向倒，佩菈姬雅·深流在船上拿水界潮門看守的工具對了一下方位：黯河上游。佩菈姬雅·深流把這個方位寫在手背上，怕自己上岸以後不信。"},{"title":"對上了","text":"十一具遺體順著黯河漂回鹽港，名冊終於對上。佩菈姬雅·深流在碼頭上，替其中一具認了身分——用水界潮門看守才知道的細節。認完，佩菈姬雅·深流走到水邊，第一次對海說了一句話。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。佩菈姬雅·深流在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。佩菈姬雅·深流替她記下其中幾具的特徵"}]}},{"id":"halvar","story":{"quote":"我信海流，不信羅盤。羅盤是人做的。哈瓦·浪濤把這句話留在鎮外·湖畔。","ideal":"遺體安置完才叫打撈。哈瓦·浪濤把這句話留在鎮外·湖畔。","bond":"三年前從鹽港出發、再沒有回來的那支船隊。哈瓦·浪濤把這句話留在鎮外·湖畔。","flaw":"拒絕得太快。哈瓦·浪濤把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖畔的碼頭邊，哈瓦船長黃銅義肢一揮，赤紅落腮鬍下笑聲如雷，張狂地邀你上船喝一杯、順便賭一把"},{"title":"哈瓦的義肢","text":"哈瓦說三年前的船隊是他送出港的，哈瓦·浪濤當時在場——哈瓦·浪濤記得那天的風向。哈瓦·浪濤把風向告訴哈瓦，哈瓦沉默很久，說：那風不對。那天不該出港。"},{"title":"慢一拍","text":"貝拉米菈的船出港時喊的節奏慢一拍。哈瓦·浪濤在船上，跟著那個節奏做自己的事。慢的那一拍沒有人划，哈瓦·浪濤知道那是給誰留的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。哈瓦·浪濤在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。哈瓦·浪濤替她記下其中幾具的特徵"}]}},{"id":"tide_cerulean","story":{"quote":"船隊沒有回來。但海把名字一個一個還了。緹德·蒼瀾把這句話留在鎮外·湖畔。","ideal":"海不騙人，海圖會。緹德·蒼瀾把這句話留在鎮外·湖畔。","bond":"黯河。它把湖裡的事帶到海，也把海裡的事帶回湖。緹德·蒼瀾把這句話留在鎮外·湖畔。","flaw":"對三年前的風向耿耿於懷。緹德·蒼瀾把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖畔的木棧橋上，緹德翹著腳晾乾外套，見你來便熱絡地招手，說想搭船去對岸就找他，價錢隨便給"},{"title":"名冊","text":"努雅莉絲說遺體比名冊多十一具，緹德·蒼瀾第一個信。做遠洋水手的人數東西從不數錯。緹德·蒼瀾替她把十一具的特徵一一記下：左手缺指、頸上有鹽痂、懷裡抱著一塊黑湖的石頭。"},{"title":"見證","text":"水下的使節團要一位陸上的中立見證人。緹德·蒼瀾去了，用遠洋水手的身分。見證的內容只有兩行：海還回來的，和海留下的。緹德·蒼瀾簽了名，覺得這兩行比一輩子的工作都重。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。緹德·蒼瀾在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。緹德·蒼瀾替她記下其中幾具的特徵"}]}},{"id":"brakka_keelhand","story":{"quote":"燈塔不是給看得見的人點的。布菈卡·龍骨手把這句話留在鎮外·湖畔。","ideal":"活人才配被帶出海。布菈卡·龍骨手把這句話留在鎮外·湖畔。","bond":"一個活人才打得出的結。布菈卡·龍骨手把這句話留在鎮外·湖畔。","flaw":"在碼頭上說謝謝說得太輕，輕到別人以為沒事。布菈卡·龍骨手把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖畔的船塢裡，布菈卡把曲尺往船板上一拍，大聲說有人拿爛料充好料，她要找出是誰"},{"title":"逆流","text":"他們沿著黯河逆流而上，布菈卡·龍骨手在船上。每過一道河灣，布菈卡·龍骨手用造船匠的辦法量一次水——愈往上愈冷，愈冷愈像海。到了湖口，布菈卡·龍骨手說：這不是河水。這是三年前的海水，一直沒有走。"},{"title":"照到對岸","text":"燈塔的光重新照到對岸那一夜，布菈卡·龍骨手在鎮外·湖畔。布菈卡·龍骨手沒有歡呼，只是把造船匠的東西收好，然後想起三年前那天的風向。這一次風是對的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。布菈卡·龍骨手在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。布菈卡·龍骨手替她記下其中幾具的特徵"}]}},{"id":"odessa_tumblerlock","story":{"quote":"海不會騙人。騙人的是海圖。奧德莎·簧鎖把這句話留在鎮廣場·萬應室。","ideal":"還回來的名字要一個一個寫。奧德莎·簧鎖把這句話留在鎮廣場·萬應室。","bond":"三年前從鹽港出發、再沒有回來的那支船隊。奧德莎·簧鎖把這句話留在鎮廣場·萬應室。","flaw":"數字對不上就讓所有人停工。奧德莎·簧鎖把這句話留在鎮廣場·萬應室。","chapters":[{"title":"水說的話","text":"萬應室門前，奧德莎聽出門後裝著一把她親手做過的鎖；那把鎖二十年前隨委託人一起沉入海裡"},{"title":"禁區礁盤","text":"莎綺絲帶他們潛進禁區，奧德莎·簧鎖負責在水面計時。珊瑚全朝一個方向倒，奧德莎·簧鎖在船上拿鎖具鑑定顧問的工具對了一下方位：黯河上游。奧德莎·簧鎖把這個方位寫在手背上，怕自己上岸以後不信。"},{"title":"對上了","text":"十一具遺體順著黯河漂回鹽港，名冊終於對上。奧德莎·簧鎖在碼頭上，替其中一具認了身分——用鎖具鑑定顧問才知道的細節。認完，奧德莎·簧鎖走到水邊，第一次對海說了一句話。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。奧德莎·簧鎖在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。奧德莎·簧鎖替她記下其中幾具的特徵"}]}},{"id":"ssarik_rivercoin","story":{"quote":"還有遺體沒有安置，就不叫打撈，叫打擾。薩里克·河幣把這句話留在鎮外·湖畔。","ideal":"遺體安置完才叫打撈。薩里克·河幣把這句話留在鎮外·湖畔。","bond":"黯河。它把湖裡的事帶到海，也把海裡的事帶回湖。薩里克·河幣把這句話留在鎮外·湖畔。","flaw":"拒絕得太快。薩里克·河幣把這句話留在鎮外·湖畔。","chapters":[{"title":"水說的話","text":"湖畔的貨棧前，薩里克翻開捲邊的帳冊一口氣報完條件，然後盯著你等一個字：成，或不成"},{"title":"哈瓦的義肢","text":"哈瓦說三年前的船隊是他送出港的，薩里克·河幣當時在場——薩里克·河幣記得那天的風向。薩里克·河幣把風向告訴哈瓦，哈瓦沉默很久，說：那風不對。那天不該出港。"},{"title":"慢一拍","text":"貝拉米菈的船出港時喊的節奏慢一拍。薩里克·河幣在船上，跟著那個節奏做自己的事。慢的那一拍沒有人划，薩里克·河幣知道那是給誰留的。"}],"relations":[{"id":"bellamira_brinehalt","text":"拒絕了死者打結的那艘船、後來自己開船送十一個名字回海的帆索長。薩里克·河幣在她的船上"},{"id":"nualith_hullshadow","text":"數到遺體比名冊多十一具就停手的打撈潛者。薩里克·河幣替她記下其中幾具的特徵"}]}},{"id":"neralis_mistgate","story":{"quote":"湖沒有對岸。對岸有燈，是另一回事。","background":"奈菈里斯·霧門在黑湖的霧裡擺渡。他寡言，記得每個乘客下船的位置，對沒有影子的旅客保持一種不冒犯的警戒。這座湖沒有對岸。所以當有人說自己從對岸來，他不是害怕，他是不肯把謊載上船。","ideal":"沒有影子的不一定是鬼。可是上船以前，要先說得出自己會在哪裡下。","bond":"霧渡口的木牌。先寫停航，後來改成：新月夜，照載。","flaw":"話太少。真正要解釋的時候，他往往只搖頭。","chapters":[{"title":"沒有對岸","text":"濃霧裡來了一群乘客，說他們從湖對岸來。奈菈里斯看他們的腳邊。沒有影子。他沒有舉篙。他說：這座湖沒有對岸。他們說燈在。他說燈可以在，岸不在。船不開。當夜他在渡口掛上木牌：停航。字寫得很直。"},{"title":"只走一趟的船","text":"魂流領航員說她只走一趟，去的時候載人，回來載影子。奈菈里斯上了那艘船。他負責唸岸上的名字。唸到的人從門前的隊伍裡走出來。他唸到一個三年前常來渡口的人，那人說：沒有影子的人上不了岸。奈菈里斯說：今天可以。這是他這個季節說得最長的句子。"},{"title":"照載","text":"撐桿碰到底的那一夜，他不在自己的船上，他在岸上接影子。人接回影子時會打一個冷顫。他扶住其中一個，等顫停。那人問現在幾年。他說了。天亮以前他把木牌翻過來，改寫：新月夜，照載。湖上以後會浮出一座城。他不打算搬走。載人是他的工作。城來了，就多載一點。"}],"relations":[{"id":"vaska_soulcurrent","text":"只走一趟、回程載影子的魂流領航員"},{"id":"garrick","text":"同一座湖上的渡船夫。門關了是他說的，木牌是奈菈里斯改的"},{"id":"corvin","text":"新月之後從另一本冊子裡來的擺渡人。兩個人後來在霧裡交換過航道"}]}},{"id":"vaska_soulcurrent","story":{"quote":"我只走一趟。去的時候載人，回來載他們丟掉的東西。","background":"瓦絲卡·魂流在湖上載靈魂。她說話只談利弊，答應過的送達就一定送到。那年秋天，利弊變了：亡者不是要走，是被人押著往回送，送回一座還在燒的爐。","ideal":"答應的航程不改。沒答應的，一寸都不加。","bond":"那一趟。來的時候船上空，回去的時候影子坐滿。","flaw":"把「只走一趟」說得太死，傷者也得照她的節奏呼吸。","chapters":[{"title":"押回去","text":"湖面上的魂流是逆的。亡者被押著往回，往湖心那處暖水下面走。瓦絲卡指給岸上的人看，說：我可以載你們去攔。只走一趟。有人問如果不夠呢。她說：那就是不夠。我不會把一趟走成兩趟，兩趟就會有人被留在中間。"},{"title":"暖水下面","text":"門在暖水下面。門前排著沒有影子的活人，不是鬼。他們被熔爐借走影子，三年來想上岸，上不了。瓦絲卡把船橫在門前，不靠岸。靠岸的是名字。擺渡人每唸一個，就有一個人上船。船滿的時候她沒有再等。她說滿了。然後調頭。"},{"title":"回來的一趟","text":"回程的船上沒有人說話。影子坐在各自的人腳邊，像暫時還不認識。靠岸時瓦絲卡第一個下，確認每個人都下了，一個沒有留在跳板上。她把空船繫好，對船說：這一趟完了。船底的水還是溫的。她沒有再出航。說好只走一趟。她守約。"}],"relations":[{"id":"neralis_mistgate","text":"在那一趟船上唸名字的霧海擺渡人"},{"id":"nell_riverhelm","text":"先看見對岸那盞燈三夜不移的河船船長"},{"id":"lyria_riverprayer","text":"說水不是髒、是太舊的河川祭司"}]}},{"id":"ulvana_fenpole","story":{"quote":"我只走一趟。去的時候載人，回來載他們丟掉的東西。","ideal":"新月夜照載","bond":"一個接回自己影子時打的冷顫。","flaw":"話少到像拒絕。烏爾瓦娜·澤篙把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"沼澤渡口，烏爾瓦娜掛出停航木牌：水位連續三晚在同一時刻降到見底，而每次退水後，蘆葦叢裡都會多出一艘沒人認領的空船"},{"title":"一趟","text":"瓦絲卡說只走一趟，烏爾瓦娜·澤篙上了船。船上沒有人說話，沼澤渡舟引路人的工具放在膝上。到了門前，烏爾瓦娜·澤篙負責把岸上的名字一個一個唸出來——唸到的，就從隊伍裡走出來上船。唸完，船滿了。"},{"title":"冷顫","text":"沒有影子的人在岸邊接回影子，接回來會打一個冷顫。烏爾瓦娜·澤篙扶著其中一個。那人顫完，低頭看自己的影子，看了很久，然後問烏爾瓦娜·澤篙：現在幾年了。烏爾瓦娜·澤篙說了。那人說：我欠了三年的帳。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。烏爾瓦娜·澤篙後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。烏爾瓦娜·澤篙在那一趟船上"}]}},{"id":"naliska_sluicemark","story":{"quote":"水不髒。水只是太舊。","ideal":"沒有影子的人也要有下船的地方。娜莉絲卡·閘標把這句話留在鎮外·湖畔。","bond":"霧渡口那塊木牌。先寫「停航」，後來改成「新月夜，照載」。娜莉絲卡·閘標把這句話留在鎮外·湖畔。","flaw":"不肯把一趟走成兩趟，即使有人被留在霧裡。娜莉絲卡·閘標把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"湖畔水閘旁，娜莉絲卡發現腰間多了一塊黃銅牌；牌上的閘門位於城裡從未挖過的一條運河"},{"title":"太舊","text":"祭司說水不髒，只是太舊。娜莉絲卡·閘標舀了一碗，用運河測繪與水閘官的方式看了很久。水裡有八百年前的灰。娜莉絲卡·閘標把那碗水倒回湖裡，說：那就讓它回去。"},{"title":"有地方落","text":"燈塔的光重新照到對岸——對岸還是沒有，但光有地方落了。娜莉絲卡·閘標在鎮外·湖畔看見那道光，第一次覺得做運河測繪與水閘官這件事有盡頭，而且盡頭是好的。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。娜莉絲卡·閘標後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。娜莉絲卡·閘標在那一趟船上"}]}},{"id":"delmara_locktide","story":{"quote":"撐桿碰到底的那一刻，我才知道自己撐了多少年。","ideal":"說好一趟就一趟。黛爾瑪菈·閘潮把這句話留在鎮外·湖畔。","bond":"湖心那一處撐桿碰不到底、水卻是暖的地方。黛爾瑪菈·閘潮把這句話留在鎮外·湖畔。","flaw":"對「對岸」這個詞零容忍。黛爾瑪菈·閘潮把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"城運河閘口，黛爾瑪菈關閉所有閘門後水位仍持續下降，彷彿整條河正被地下某張巨口吞飲"},{"title":"排在門前","text":"湖心的門前排著沒有影子的人。黛爾瑪菈·閘潮在船上認出其中一個——三年前常來鎮外·湖畔的。黛爾瑪菈·閘潮叫了他的名字，他轉過來，說：我一直想回去，可是沒有影子的人上不了岸。黛爾瑪菈·閘潮說：我帶你上。"},{"title":"照載","text":"霧渡口的木牌換成「新月夜，照載」。黛爾瑪菈·閘潮看見的時候笑了一下。樞紐鬆了，城會浮上來，湖邊的人沒有一個打算搬走。黛爾瑪菈·閘潮也不搬。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。黛爾瑪菈·閘潮後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。黛爾瑪菈·閘潮在那一趟船上"}]}},{"id":"mosshell_caliper","story":{"quote":"新月夜，照載。","ideal":"水太舊就讓它回去。苔殼·尺把這句話留在鎮外·湖畔。","bond":"一個接回自己影子時打的冷顫。苔殼·尺把這句話留在鎮外·湖畔。","flaw":"扶著人的時候不看對方的眼睛。苔殼·尺把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"湖畔的水閘旁，苔殼緩緩抬頭說他算了三遍——這條運河的水少了一成，而水沒有流去該去的地方"},{"title":"少的那一成","text":"水少了一成，沒有流去該去的地方。苔殼·尺用運河工程師的辦法追了三天，追到湖心暖水那一處。水是從那裡往下走的——下面有東西在喝。苔殼·尺把這件事告訴渡船夫，渡船夫說：我知道。我撐桿碰不到底。"},{"title":"碰到底","text":"撐桿碰到底那一刻，苔殼·尺在岸上。渡船夫沒有歡呼，只說「門關了」。苔殼·尺把運河工程師的東西收進袋子，坐在水邊坐到天亮。水暖回來的速度很慢，一度一度的，像有人在數。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。苔殼·尺後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。苔殼·尺在那一趟船上"}]}},{"id":"naia_tidewhisper","story":{"quote":"湖沒有對岸。對岸有燈，是另一回事。奈雅·潮語把這句話留在鎮外·湖畔。","ideal":"新月夜照載。奈雅·潮語把這句話留在鎮外·湖畔。","bond":"霧渡口那塊木牌。先寫「停航」，後來改成「新月夜，照載」。奈雅·潮語把這句話留在鎮外·湖畔。","flaw":"話少到像拒絕。奈雅·潮語把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"湖畔碼頭上，奈雅的潮汐圖浮出一條通往古地城的新暗流；她說那裡昨晚以前還是實心岩層"},{"title":"一趟","text":"瓦絲卡說只走一趟，奈雅·潮語上了船。船上沒有人說話，潮汐製圖師的工具放在膝上。到了門前，奈雅·潮語負責把岸上的名字一個一個唸出來——唸到的，就從隊伍裡走出來上船。唸完，船滿了。"},{"title":"冷顫","text":"沒有影子的人在岸邊接回影子，接回來會打一個冷顫。奈雅·潮語扶著其中一個。那人顫完，低頭看自己的影子，看了很久，然後問奈雅·潮語：現在幾年了。奈雅·潮語說了。那人說：我欠了三年的帳。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。奈雅·潮語後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。奈雅·潮語在那一趟船上"}]}},{"id":"lyria_riverprayer","story":{"quote":"沒有影子的不一定是鬼。有時候只是影子被借走了。莉莉雅·河禱把這句話留在鎮外·湖畔。","ideal":"沒有影子的人也要有下船的地方。莉莉雅·河禱把這句話留在鎮外·湖畔。","bond":"湖心那一處撐桿碰不到底、水卻是暖的地方。莉莉雅·河禱把這句話留在鎮外·湖畔。","flaw":"不肯把一趟走成兩趟，即使有人被留在霧裡。莉莉雅·河禱把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"湖畔的石壇前，莉莉雅捧著銀碗說，這條河的水在上游被人動過，而她已經祭了三天都淨不乾淨"},{"title":"太舊","text":"祭司說水不髒，只是太舊。莉莉雅·河禱舀了一碗，用河川祭司的方式看了很久。水裡有八百年前的灰。莉莉雅·河禱把那碗水倒回湖裡，說：那就讓它回去。"},{"title":"有地方落","text":"燈塔的光重新照到對岸——對岸還是沒有，但光有地方落了。莉莉雅·河禱在鎮外·湖畔看見那道光，第一次覺得做河川祭司這件事有盡頭，而且盡頭是好的。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。莉莉雅·河禱後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。莉莉雅·河禱在那一趟船上"}]}},{"id":"solenne_beacongear","story":{"quote":"我只走一趟。去的時候載人，回來載他們丟掉的東西。索倫娜·光機把這句話留在鎮外·湖畔。","ideal":"說好一趟就一趟。索倫娜·光機把這句話留在鎮外·湖畔。","bond":"一個接回自己影子時打的冷顫。索倫娜·光機把這句話留在鎮外·湖畔。","flaw":"對「對岸」這個詞零容忍。索倫娜·光機把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"湖畔的燈塔頂，索倫娜擦亮巨大的透鏡說，這幾夜的光照不到對岸，像被什麼吸走了"},{"title":"排在門前","text":"湖心的門前排著沒有影子的人。索倫娜·光機在船上認出其中一個——三年前常來鎮外·湖畔的。索倫娜·光機叫了他的名字，他轉過來，說：我一直想回去，可是沒有影子的人上不了岸。索倫娜·光機說：我帶你上。"},{"title":"照載","text":"霧渡口的木牌換成「新月夜，照載」。索倫娜·光機看見的時候笑了一下。樞紐鬆了，城會浮上來，湖邊的人沒有一個打算搬走。索倫娜·光機也不搬。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。索倫娜·光機後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。索倫娜·光機在那一趟船上"}]}},{"id":"marlow_beacon","story":{"quote":"水不髒。水只是太舊。馬洛·烽塔把這句話留在鎮外·湖畔。","ideal":"水太舊就讓它回去。馬洛·烽塔把這句話留在鎮外·湖畔。","bond":"霧渡口那塊木牌。先寫「停航」，後來改成「新月夜，照載」。馬洛·烽塔把這句話留在鎮外·湖畔。","flaw":"扶著人的時候不看對方的眼睛。馬洛·烽塔把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"湖畔的燈塔階梯上，馬洛提燈擋住去路，瞇著淺藍的眼睛說對岸夜裡有人在打訊號，而那裡沒有人住"},{"title":"少的那一成","text":"水少了一成，沒有流去該去的地方。馬洛·烽塔用燈塔守望人的辦法追了三天，追到湖心暖水那一處。水是從那裡往下走的——下面有東西在喝。馬洛·烽塔把這件事告訴渡船夫，渡船夫說：我知道。我撐桿碰不到底。"},{"title":"碰到底","text":"撐桿碰到底那一刻，馬洛·烽塔在岸上。渡船夫沒有歡呼，只說「門關了」。馬洛·烽塔把燈塔守望人的東西收進袋子，坐在水邊坐到天亮。水暖回來的速度很慢，一度一度的，像有人在數。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。馬洛·烽塔後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。馬洛·烽塔在那一趟船上"}]}},{"id":"nerissa_pearlnet","story":{"quote":"撐桿碰到底的那一刻，我才知道自己撐了多少年。涅莉莎·珠網把這句話留在鎮外·湖畔。","ideal":"新月夜照載。涅莉莎·珠網把這句話留在鎮外·湖畔。","bond":"湖心那一處撐桿碰不到底、水卻是暖的地方。涅莉莎·珠網把這句話留在鎮外·湖畔。","flaw":"話少到像拒絕。涅莉莎·珠網把這句話留在鎮外·湖畔。","chapters":[{"title":"湖說的話","text":"湖畔的礁石旁，涅莉莎浮出水面攤開手掌，掌心的珠子帶著一道黑紋，她只說了三個字：湖底有事"},{"title":"一趟","text":"瓦絲卡說只走一趟，涅莉莎·珠網上了船。船上沒有人說話，採珠人的工具放在膝上。到了門前，涅莉莎·珠網負責把岸上的名字一個一個唸出來——唸到的，就從隊伍裡走出來上船。唸完，船滿了。"},{"title":"冷顫","text":"沒有影子的人在岸邊接回影子，接回來會打一個冷顫。涅莉莎·珠網扶著其中一個。那人顫完，低頭看自己的影子，看了很久，然後問涅莉莎·珠網：現在幾年了。涅莉莎·珠網說了。那人說：我欠了三年的帳。"}],"relations":[{"id":"neralis_mistgate","text":"拒載沒有影子乘客的擺渡人。涅莉莎·珠網後來跟他一起把影子載回來"},{"id":"vaska_soulcurrent","text":"只走一趟的魂流領航員。涅莉莎·珠網在那一趟船上"}]}}]});
